L2_1 = {}
L2_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@2#Talk"
L2_1.m_CutScenProcessKey = 2
L2_1.m_CutScenID = 4500107
L2_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Talk_KOREA = "첫 번째 정착자들은 세상에 큰 재앙이 닥칠 것을 예견했다."
L2_1.m_fTalkTime = 0.03
L2_1.m_bTalkCenterFadeIn = true
L2_1.m_Talk_JPN = "最初の定着者は世界に大きな災いが訪れることを予見したんじゃ。"
L2_1.m_Talk_ENG = "The First Settlers predicted that a great disaster would befall this world."
L2_1.m_Talk_TWN = "第一批定居者預言世界將遭遇一場浩劫。"
L2_1.m_Talk_THA = "ผู้ก่อตั้งรกรากกลุ่มแรกเคยพยากรณ์ไว้ว่าโลกใบนี้ต้องเผชิญหายนะครั้งใหญ่"
L2_1.m_Talk_VTN = "Tiền Nhân dự đoán rằng một thảm họa lớn sẽ xảy ra trên thế giới này."
L2_1.m_Talk_SCN = "第一批定居者预见了会有大灾难降临世界。"
L2_1.m_Talk_DEU = "Die ersten Siedler sagten voraus, dass dieser Welt eine große Katastrophe widerfahren würde."
L2_1.m_Talk_FRA = "Les premiers Pionniers avaient prédit qu'une grande catastrophe arriverait à ce monde."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 4500107
L3_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "그래서 숲의 요정들이 속삭여 준 지식으로 낙원문이라는 커다란 탑을 세웠다고 하지."
L3_1.m_fTalkTime = 0.03
L3_1.m_bTalkCenterFadeIn = true
L3_1.m_Talk_JPN = "だから、森の妖精たちがささやいてくれた知識をもって楽園の門という大きな塔を建てたという。"
L3_1.m_Talk_ENG = "So they used the knowledge whispered by the forest fairies to erect the gigantic tower known as \"Avalon's Gate\"."
L3_1.m_Talk_TWN = "因此藉由森林精靈私語的知識，築起一座名為樂園門的巨塔。"
L3_1.m_Talk_THA = "พวกเขาเลยใช้ความรู้ที่ภูตไพรกระซิบบอกมาสร้างแท่งโอเบลิสก์ยักษ์ที่ชื่อว่า \"ประตูของอะวาลอน\""
L3_1.m_Talk_VTN = "Vì vậy, họ đã sử dụng kiến thức được thì thầm bởi tinh linh rừngđể xây dựng tháp khổng lồ được gọi là \"Cổng Avalon\"."
L3_1.m_Talk_SCN = "他们从森林妖精们的窃窃私语中学会了建造名为阿瓦隆之门的高塔。"
L3_1.m_Talk_DEU = "Also nutzten sie das von den Waldfeen geflüsterte Wissen, um den gigantischen Turm zu errichten, der als „Avalons Tor“ bekannt ist."
L3_1.m_Talk_FRA = "Ils ont donc utilisé les connaissances chuchotées par les Fées de la forêt pour ériger une gigantesque tour, la Porte d'Avalon."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 4500107
L4_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "어떤 원리인지 우리 같은 무지렁이들은 알 수 없지만, 낙원문은 나라를 침식에서 지켜줬다네."
L4_1.m_fTalkTime = 0.03
L4_1.m_bTalkCenterFadeIn = true
L4_1.m_Talk_JPN = "わしらのような無学な者にはどんな原理かわからんが、楽園の門は国を侵食から守ってくれたそうじゃ。"
L4_1.m_Talk_ENG = "Although ordinary people like us don't know the principles behind it, Avalon's Gate saved this country from the Corruption."
L4_1.m_Talk_TWN = "雖然像我們這種凡夫俗子，無法知道是什麼原理，但樂園門確實保護國家免於侵蝕之災。"
L4_1.m_Talk_THA = "ถึงคนธรรมดาอย่างเราจะไม่รู้หลักการเบื้องหลัง\nแต่ประตูของอะวาลอนก็ช่วยประเทศนี้ไว้จากการคอร์รัปชั่น"
L4_1.m_Talk_VTN = "Mặc dù những người bình thường như chúng ta không biết các nguyên tắc đằng sau nó, nhưng Cổng Avalon đã cứu đất nước này khỏi Sự Ăn Mòn."
L4_1.m_Talk_SCN = "虽然像我们这样愚笨的后人不知道它的具体原理，但门保护了国家免受侵蚀。"
L4_1.m_Talk_DEU = "Obwohl gewöhnliche Menschen wie wir die Prinzipien dieser Bauweise und Funktion nicht nachvollziehen können, hat Avalons Tor dieses Land vor der Verderbnis gerettet."
L4_1.m_Talk_FRA = "Bien que les gens ordinaires comme nous ne connaissent pas les principes de sa conception, c'est la Porte d'Avalon qui tenu ce pays hors de la Corruption tout ce temps."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 4500107
L5_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "무서운 침식체들도 낙원문이 건재할 때는 맥을 못 췄지."
L5_1.m_fTalkTime = 0.03
L5_1.m_bTalkCenterFadeIn = true
L5_1.m_Talk_JPN = "恐ろしい侵食体も楽園の門が健在だった頃は力を発揮できなかった。"
L5_1.m_Talk_ENG = "Those nasty C.O.s didn't stand a chance when Avalon's Gate was standing tall."
L5_1.m_Talk_TWN = "在樂園門還在時，連可怕的侵蝕體都無計可施。"
L5_1.m_Talk_THA = "วัตถุคอร์รัปต์ร้ายกาจพวกนั้นไม่มีโอกาสล่วงล้ำเข้ามาเมื่อประตูของอะวาลอนยังคงตั้งตระหง่าน"
L5_1.m_Talk_VTN = "Những V.T.A.M khó chịu đó không có cơ hội khi Cổng Avalon đứng sừng sững."
L5_1.m_Talk_SCN = "只要门还高高耸立着，可怕的侵蚀体就会变得老实。"
L5_1.m_Talk_DEU = "Sogar diese fiesen C.°O.s hatten keine Chance gegen Avalons Tor."
L5_1.m_Talk_FRA = "Quand elle était encore debout, ces horribles monstres n'avaient aucune chance."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 4500107
L6_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Talk_KOREA = "하지만 침식의 날이 시작된 지 얼마 지나지 않아 낙원문은 갑자기 가동을 멈췄어."
L6_1.m_fTalkTime = 0.03
L6_1.m_bTalkCenterFadeIn = true
L6_1.m_Talk_JPN = "じゃが、侵食の日が始まって間もない頃、楽園の門は急に稼働を停止したんじゃ。"
L6_1.m_Talk_ENG = "However, only a few days after the Day of Corruption, Avalon's Gate suddenly stopped working."
L6_1.m_Talk_TWN = "不過在侵蝕之日開始後不久，樂園門突然停止運作。"
L6_1.m_Talk_THA = "แต่ยังไงก็ตาม หลังจากวันคอร์รัปชั่นได้ไม่กี่วัน จู่ๆ ประตูของอะวาลอนก็หยุดทำงาน"
L6_1.m_Talk_VTN = "Tuy nhiên, chỉ vài ngày sau Ngày Ăn Mòn, Cổng Avalon đột ngột ngừng hoạt động."
L6_1.m_Talk_SCN = "然而侵蚀日开始后没多久，门突然停止了运行。"
L6_1.m_Talk_DEU = "Doch nur wenige Tage nach dem Tag der Verderbnis funktionierte Avalons Tor plötzlich nicht mehr."
L6_1.m_Talk_FRA = "Mais peu après le Jour de la Corruption, la Porte d'Avalon a soudainement cessé de fonctionner."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 4500107
L7_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Talk_KOREA = "그러자 노르드나빅 전역에 침식 현상이 일어났고, 지옥이 펼쳐졌지."
L7_1.m_fTalkTime = 0.03
L7_1.m_bTalkCenterFadeIn = true
L7_1.m_Talk_JPN = "同時にノルドナビックの全域に侵食現象が起こり、地獄と化した。"
L7_1.m_Talk_ENG = "With the Counterside Effect sweeping across Nordnavik, all hell broke loose."
L7_1.m_Talk_TWN = "於是在諾爾德萊比全區發生侵蝕現象，彷彿人間地獄一般。"
L7_1.m_Talk_THA = "พอปรากฏการณ์เคาน์เตอร์ไซด์แพร่กระจายไปทั่วนอร์ดเนวิก เรื่องราวก็อย่างกับนรกแตก"
L7_1.m_Talk_VTN = "Khi Hiệu Ứng Ăn Mòn càn quét khắp Nordnavik, mọi thứ đã trở thành địa ngục trần thế."
L7_1.m_Talk_SCN = "侵蚀爆发了，诺德纳维克变成了人间地狱。"
L7_1.m_Talk_DEU = "Als der Counterside-Effekt über Nordnavik hereinbrach, brach die Hölle los."
L7_1.m_Talk_FRA = "Les Effets du Contremonde ont alors submergé Nordnavik, et nos vies sont devenues un enfer."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 4500107
L8_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "그 날의 전말을 되돌아볼 여력이 생겼을 즈음엔 이미 나라가 엉망진창이었어."
L8_1.m_fTalkTime = 0.03
L8_1.m_bTalkCenterFadeIn = true
L8_1.m_Talk_JPN = "あの日の顛末を振り返る余力ができた頃にはもう国はボロボロになっておった。"
L8_1.m_Talk_ENG = "By the time we were able to look back at this catastrophe, the country was already in shambles."
L8_1.m_Talk_TWN = "當我有餘力去回想那天的始末時，國家已經是一團糟。"
L8_1.m_Talk_THA = "ตอนที่เรามองย้อนกลับไปยังมหาหายนะนั้นได้ ประเทศนี้ก็ย่อยยับไปหมดแล้ว"
L8_1.m_Talk_VTN = "Vào thời điểm chúng ta có thể nhìn lại thảm họa này thì đất nước đã chìm trong hỗn loạn."
L8_1.m_Talk_SCN = "当人们有余力回顾那天的来龙去脉时，国家已经摇摇欲坠了。"
L8_1.m_Talk_DEU = "Als man die Energie hatte, auf die ganze Geschichte dieses Tages zurückzublicken, lag das Land bereits in Trümmern."
L8_1.m_Talk_FRA = "Avant même que nous ayons eu le temps de comprendre ce qui s'est passé, le pays était déjà en ruine."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 4500107
L9_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "성자들은 모두 침식체에게 맞서다 죽고, 임금께선 후계자를 결정하지도 못한 채 승하하셨지."
L9_1.m_fTalkTime = 0.03
L9_1.m_bTalkCenterFadeIn = true
L9_1.m_Talk_JPN = "聖者はみな侵食体に立ち向かって死に、王は後継者を決めることもできないまま崩御された。"
L9_1.m_Talk_ENG = "All Helgons had died fending off C.O.s, and the king passed away without declaring an heir to the throne."
L9_1.m_Talk_TWN = "聖者們全都在對抗侵蝕體時死去，國王也在來不及决定繼承者的情况下便駕崩。"
L9_1.m_Talk_THA = "เฮลกอนทุกคนตายหมดในการขับไล่วัตถุคอร์รัปต์ และพระราชาก็สวรรคตโดยไม่ได้มีการประกาศตัวองค์รัชทายาทผู้สืบบัลลังก์"
L9_1.m_Talk_VTN = "Tất cả Helgon đã chết khi chống lại V.T.A.M, nhà vua đã qua đời mà không kịp tuyên bố người thừa kế ngai vàng."
L9_1.m_Talk_SCN = "圣者们在对抗侵蚀体的过程中全部牺牲，国王甚至还没有确定下继承人就已经驾崩。"
L9_1.m_Talk_DEU = "Alle Heiligen starben im Kampf gegen die C.°O.s und der König starb, ohne einen Thronfolger zu ernennen."
L9_1.m_Talk_FRA = "Tous les Vertueux avaient péri face au déluge d'Objets Corrompus. Ainsi que notre souverain, avant même de pouvoir nommer un héritier."
