L12_1 = {}
L12_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 4500107
L12_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "그리고 임금의 총애를 받던 총사대장 큐리안은……."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "そして王の寵愛を受けていた銃士隊長キュリアンは……"
L12_1.m_Talk_ENG = "And Curian, the king's most beloved soldier..."
L12_1.m_Talk_TWN = "而國王的心腹 隊長庫里安……"
L12_1.m_Talk_THA = "และคิวเรี่ยน ทหารคนโปรดที่สุดของพระราชา..."
L12_1.m_Talk_VTN = "Và Curian, người lính yêu quý nhất của nhà vua..."
L12_1.m_Talk_SCN = "而深得国王信任的奎里安队长……"
L12_1.m_Talk_DEU = "Und Curian, der Lieblingssoldat des Königs ..."
L12_1.m_Talk_FRA = "Quant à Curian, le Général des Mousquetaires et favori du roi..."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 4500107
L13_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "낙원문의 중추인 열쇠를 가지고 어디론가 떠났다는 기록을 마지막으로 행방이 묘연해졌다네."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "楽園の門の要である鍵を持ってどこかへ向かったという記録を最後に、行方不明になったのじゃ。"
L13_1.m_Talk_ENG = "Records show that he took the Key from Avalon's Gate and disappeared."
L13_1.m_Talk_TWN = "則是帶著樂園門的鑰匙下落不明。"
L13_1.m_Talk_THA = "บันทึกบอกว่าเขาเอากุญแจไปจากประตูของอะวาลอนแล้วก็หายตัวไป"
L13_1.m_Talk_VTN = "Hồ sơ ghi lại anh ta đã lấy Chìa Khóa từ Cổng Avalon và biến mất."
L13_1.m_Talk_SCN = "最后只留下他拿着门的中枢——钥匙去了什么地方的记录，便下落不明了。"
L13_1.m_Talk_DEU = "Aufzeichnungen zufolge soll er den Schlüssel von Avalons Tor genommen haben und verschwunden sein."
L13_1.m_Talk_FRA = "L'histoire retient qu'il s'est emparé de la clé de la Porte d'Avalon avant de s'évanouir dans la nature."
