L16_1 = {}
L16_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 4500107
L16_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Talk_KOREA = "그래서 재건단은 파괴된 낙원문을 복원하려고 시도 중이야. 나라의 흥망을 가른 사건이니까."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "それで再建団は破壊された楽園の門の復元しようとしているんだ。国の興亡を決めた事件だからね。"
L16_1.m_Talk_ENG = "The Alliance is trying its best to rebuild Avalon's Gate since it was what determined the fate of this country."
L16_1.m_Talk_TWN = "因此重建委員會正試圖復原遭破壞的樂園門，因爲此事攸關國家存亡。"
L16_1.m_Talk_THA = "พันธมิตรพยายามสร้างประตูของอะวาลอนขึ้นมาใหม่\nอย่างสุดกำลัง เพราะนั่นคือสิ่งตัดสินชะตากรรมของประเทศนี้"
L16_1.m_Talk_VTN = "Liên Minh đang cố gắng hết sức để xây dựng lại Cổng Avalon vì nó là thứ quyết định số phận của đất nước này."
L16_1.m_Talk_SCN = "贵族们一直以来都在尝试恢复被破坏的阿瓦隆之门。因为这是决定国家兴亡的大事。"
L16_1.m_Talk_DEU = "Die Wiederaufbaustiftung versucht ihr Bestes, um Avalons Tor wieder aufzubauen, da es über das Schicksal dieses Landes entscheidet."
L16_1.m_Talk_FRA = "À l'heure actuelle, l'Alliance fait de son mieux pour reconstruire la Porte d'Avalon. Après tout, il en va de la survie de notre pays."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 4500107
L17_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "하지만 지식을 전수 받은 왕족이 없는 한, 그건 결국 모조품에 지나지 않아."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "でも知識を授けられた王族がいない限り、それは結局レプリカに過ぎない。"
L17_1.m_Talk_ENG = "But without the knowledge passed down to the Royal bloodline, it'll be nothing more than a replica of the original."
L17_1.m_Talk_TWN = "但若沒有得知知識的皇族，那終究只是仿冒品而已。"
L17_1.m_Talk_THA = "แต่พอไม่มีความรู้ที่สืบทอดกันมาตามสายเลือดราชวงศ์ ที่ทำได้เลยเป็นแค่ของเลีบนแบบเท่านั้น"
L17_1.m_Talk_VTN = "Nhưng nếu không có kiến thức được truyền lại cho dòng máu Hoàng gia, nó sẽ chẳng khác gì một bản sao của bản gốc."
L17_1.m_Talk_SCN = "可是在缺少学习过相关知识的王族的情况下，最后建成的也不过是个仿制品。"
L17_1.m_Talk_DEU = "Aber ohne das Wissen, das an die königliche Blutlinie weitergegeben wurde, wird es nichts weiter als eine Nachbildung des Originals sein."
L17_1.m_Talk_FRA = "Mais sans les connaissances héritées par la famille royale, la nouvelle porte ne sera rien de plus qu'une réplique de l'originale. Une coquille vide."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 4500107
L18_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "우리는 오랫동안 침식에 시달려 왔네. 침식은 우리의 모든 것을 앗아갔지."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "わしらは長らく侵食に苦しんできたんじゃ。侵食は全てを奪っていったからのう。"
L18_1.m_Talk_ENG = "We've suffered for too long from the C.O.s. The Corruption took everything away from us."
L18_1.m_Talk_TWN = "我們長期為侵蝕所苦，侵蝕奪走我們的一切。"
L18_1.m_Talk_THA = "พวกเราทุกข์ทรมานกับวัตถุคอร์รัปต์มานาน การคอร์รัปชั่นเอาทุกอย่างไปจากเราจนหมด"
L18_1.m_Talk_VTN = "Chúng tôi đã phải chịu đựng V.T.A.M quá lâu. Sự Ăn Mòn đã lấy đi mọi thứ của chúng tôi."
L18_1.m_Talk_SCN = "长久以来，我们一直在遭受侵蚀的折磨。侵蚀夺走了我们的一切。"
L18_1.m_Talk_DEU = "Wir haben zu lange unter den C.°O.s gelitten. Die Verderbnis hat uns alles genommen."
L18_1.m_Talk_FRA = "La Corruption nous a pris. Nous ne comptons plus les jours que nous avons passé à affronter ces maudits O.C."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 4500107
L19_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "살기 위해 고향을 떠나 여기까지 왔건만, 침식의 고통은 하루도 우릴 놓아 주지 않았어."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "生きるために故郷を離れてここまで来たのに、侵食の苦痛は一日もわしらを放っておいてくれなかった。"
L19_1.m_Talk_ENG = "I fled my hometown and came all the way here. But the suffering caused by the Corruption wouldn't let go for even just one day."
L19_1.m_Talk_TWN = "爲了活下去，我們離開家鄉來到這裡，但侵蝕的痛苦卻沒有一天放過我們。"
L19_1.m_Talk_THA = "ผมหนีจากบ้านเกิดตัวเองแล้วดั้นด้นมาถึงนี่\nแต่ความทุกข์ทรมานที่คอร์รัปชั่นสร้างขึ้นไม่เคยผ่านพ้นไปเลยแม้แต่วันเดียว"
L19_1.m_Talk_VTN = "Tôi đã trốn khỏi quê hương và đến tận đây. Nhưng những đau khổ do Sự Ăn Mòn gây ra sẽ không buông bỏ dù chỉ một ngày."
L19_1.m_Talk_SCN = "为了活下去，我们背井离乡、来到了这里，但侵蚀的痛苦一天也没放过我们。"
L19_1.m_Talk_DEU = "Ich bin aus meiner Heimatstadt geflohen und bin den ganzen Weg hierher gekommen. Doch das durch die Verderbnis verursachte Leid ließ einfach nicht nach."
L19_1.m_Talk_FRA = "J'ai fui ma ville natale pour venir ici. Mais la souffrance causée par la Corruption ne m'a jamais lâchée, pas même pour une seule journée."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 4500107
L20_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "그러던 어느날 우리 앞에 나타난 거라네."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "そんなある日、私たちの前に現われたのじゃ。"
L20_1.m_Talk_ENG = "Then one day, you appeared."
L20_1.m_Talk_TWN = "然而某一天，在我們面前，"
L20_1.m_Talk_THA = "จนกระทั่งวันหนึ่ง คุณก็ปรากฏตัวขึ้น"
L20_1.m_Talk_VTN = "Rồi một ngày, anh xuất hiện."
L20_1.m_Talk_SCN = "然后突然有一天，有个人突然出现在了我们面前。"
L20_1.m_Talk_DEU = "Doch eines Tages bist du dann aufgetaucht."
L20_1.m_Talk_FRA = "Et puis un jour, tu es apparu devant nous."
