L22_1 = {}
L22_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 4500107
L22_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L22_1.m_Talk_KOREA = "자신이 큐리안이라고 주장하는 젊은 친구가 말이야."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "自身をキュリアンだと主張する若者がな。"
L22_1.m_Talk_ENG = "A young fellow who went by the name \"Curian\"."
L22_1.m_Talk_TWN = "出現一個自稱是庫里安的年輕人。"
L22_1.m_Talk_THA = "ชายหนุ่มผู้ใช้ชื่อว่า \"คิวเรี่ยน\""
L22_1.m_Talk_VTN = "Một chàng trai trẻ có tên \"Curian\"."
L22_1.m_Talk_SCN = "一个自称是奎里安的年轻人。"
L22_1.m_Talk_DEU = "Ein junger Mann, der den Namen „Curian“ trug."
L22_1.m_Talk_FRA = "Toi, Curian, un fantôme du passé."
