L24_1 = {}
L24_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 4500107
L24_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "알고 있던 것과 다른 점이 있어? 아니면 다른 기억이 떠올랐다거나."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "知っていることと違うところはある？　それとも別の記憶を思い出したとか。"
L24_1.m_Talk_ENG = "Is there something you'd like to add? Or did you remember something?"
L24_1.m_Talk_TWN = "這和你認知的有什麼差異嗎？或是有想起什麼嗎？"
L24_1.m_Talk_THA = "มีอะไรอยากเพิ่มเติมมั้ย? หรือจำอะไรได้บ้างรึเปล่า?"
L24_1.m_Talk_VTN = "Anh muốn bổ sung thêm gì không? Hay anh đã nhớ ra điều gì?"
L24_1.m_Talk_SCN = "跟你知道的有什么不一样的地方吗？或者让你想起了别的什么事？"
L24_1.m_Talk_DEU = "Möchtest du dem etwas hinzufügen? Oder kommen deine Erinnerungen langsam zurück?"
L24_1.m_Talk_FRA = "Tu as quelque chose à ajouter ? Peut-être un souvenir qui aurait ressurgi dans ta mémoire ?"
L25_1 = {}
L25_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 4500107
L25_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "나는……. 낙원문의 기능이 한계에 달했으니 열쇠를 운반해야 한다는 명령을 받았다."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "私は……楽園の門の機能が限界に達したから鍵を運べと命令された。"
L25_1.m_Talk_ENG = "I... was ordered to move the Key as Avalon's Gate reached its limit."
L25_1.m_Talk_TWN = "我……我收到命令，説樂園門的功能已經達到極限，需要移動鑰匙。"
L25_1.m_Talk_THA = "ผม... ได้รับคำสั่งให้เคลื่อนย้ายกุญแจไปเพราะประตูของอะวาลอนถึงขีดจำกัดแล้ว"
L25_1.m_Talk_VTN = "Tôi... được lệnh di chuyển Chìa Khóa khi Cổng Avalon đạt đến giới hạn."
L25_1.m_Talk_SCN = "我……接到了阿瓦隆之门的功能已经达到了极限，必须运走钥匙的命令。"
L25_1.m_Talk_DEU = "Mir ... wurde befohlen, den Schlüssel an einen anderen Ort zu transportieren, als Avalons Tor sein Limit erreichte."
L25_1.m_Talk_FRA = "J'ai... reçu l'ordre de déplacer la clé quand la Porte d'Avalon a atteint sa limite."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "BORDER_ACT1_STAGE3_START@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 4500107
L26_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_DESPAIR"
L26_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "그렇게 남부로 향하던 중 침식체에게 공격 받은 마을을 도왔고……."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "それで南部に向かう途中、侵食体から攻撃された村を救い……"
L27_1 = "As I was heading south, I helped a village that was being attacked by C.O.s, and..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "於是我們便出發南下，在路途中還幫助遭遇侵蝕體攻擊的村莊………"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ระหว่างที่ผมมุ่งหน้าไปทางใต้ ผมได้ช่วยหมู่บ้านที่กำลังโดนวัตถุคอร์รัปต์โจมตี แล้วก็..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Khi tôi đang đi về phía nam, tôi đã giúp một ngôi làng đang bị V.T.A.M tấn công, và..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "在我们朝着南部进发的途中，帮助了一个被侵蚀体攻击的村子……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Als ich nach Süden fuhr, half ich einem Dorf, das von C.°O.s angegriffen wurde, und ..."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors que nous faisions route vers le sud, mes hommes et moi-même avons décidé de faire un détour pour secourir un village qui subissait une attaque d'Objets Corrompus..."
L26_1.m_Talk_FRA = L27_1
