L30_1 = "거기서 어떤 기이한 존재와 마주쳤지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そこである奇妙な存在と出くわしたんだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "That's where I encountered this strange one."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我在那裡遇到一個詭異的傢伙。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ตอนนั้นเองที่ผมเจอคนแปลกๆ เข้า"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đó là nơi tôi gặp người kỳ lạ này."
L29_1.m_Talk_VTN = L30_1
L30_1 = "在那里我们遇到了某个奇怪的存在。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Dort bin ich auf dieses seltsame Geschöpf gestoßen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "C'est alors que j'ai fait la rencontre de cette étrange créature."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "BORDER_ACT1_STAGE3_START@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4500107
L30_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L31_1 = "그건 우리가 알던 침식체는 아니었지만, 인간 역시 아니었어."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "それは我々の知っている侵食体ではなかったが、人間でもなかった。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "She was not like any C.O. we've seen. But she wasn't a person either."
L30_1.m_Talk_ENG = L31_1
L31_1 = "那不是我們所認知的侵蝕體，但也不是人類。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เธอไม่เหมือนวัตถุคอร์รัปต์ที่ผมเคยเจอมาก่อน แต่เธอก็ไม่ใช่คนด้วย"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô ta không giống bất kỳ V.T.A.M nào chúng tôi từng thấy. Nhưng cô ta cũng không phải là người."
L30_1.m_Talk_VTN = L31_1
L31_1 = "她既不是我们所知道的侵蚀体，也不是人类。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Sie war kein gewöhnliches C. O., aber sie war auch kein Mensch."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Un être indescriptible. Pas un Objets Corrompu, mais pas un être humain non plus."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
