L32_1 = {}
L33_1 = "BORDER_ACT1_STAGE3_START@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4500107
L32_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L32_1.m_Pos = "C"
L33_1 = "놈과 마주친 뒤의 기억은…… 그저 병사들의 절규와 비명뿐이야."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "やつと出会った後の記憶は……ただ兵士たちの絶叫と悲鳴だけだ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "The last thing I remember after her is... the screams and despair of my men."
L32_1.m_Talk_ENG = L33_1
L33_1 = "遇見那傢伙之後的記憶……只有士兵們的吶喊和慘叫。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "สิ่งสุดท้ายที่ผมจำได้หลังจากเธอปรากฏตัวขึ้นก็คือ... เสียงกรีดร้องและความสิ้นหวังจากคนของผม"
L32_1.m_Talk_THA = L33_1
L33_1 = "Điều cuối cùng tôi nhớ sau cô ấy là... tiếng la hét và tuyệt vọng của đồng đội của tôi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "之后的记忆……就只剩下士兵们的呼喊和惨叫了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das Letzte, woran ich mich noch erinnern kann, sind ... die Schreie und die Verzweiflung meiner Männer."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Après ça, je ne me souviens que d'un cri... et d'un déluge de désespoir."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "BORDER_ACT1_STAGE3_START@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4500107
L33_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L33_1.m_Pos = "C"
L34_1 = "으음."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ううむ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Mm."
L33_1.m_Talk_ENG = L34_1
L34_1 = "嗯嗯。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "อืม"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hừm."
L33_1.m_Talk_VTN = L34_1
L34_1 = "嗯。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hmm."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hum."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "BORDER_ACT1_STAGE3_START@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4500107
L34_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L34_1.m_Pos = "C"
L35_1 = "솔직히 나는 자네 이야기를 믿을 수 없네."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "正直わしはお前さんの話を信じられん。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "To be frank, I'm not at all convinced by your story."
L34_1.m_Talk_ENG = L35_1
L35_1 = "老實說，我不相信你說的。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พูดตามตรงนะ ผมไม่ได้เชื่อเรื่องของคุณไปเสียหมด"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nói thẳng là, tôi hoàn toàn không bị thuyết phục bởi câu chuyện của anh."
L34_1.m_Talk_VTN = L35_1
L35_1 = "说实话，我不相信你的话。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Um ehrlich zu sein, bin ich von deiner Geschichte überhaupt nicht überzeugt."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Pour être franc, je ne suis pas du tout convaincu par ton histoire."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "BORDER_ACT1_STAGE3_START@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4500107
L35_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L35_1.m_Pos = "C"
L36_1 = "하지만 여기 외성에 사는 주민들은 침식으로 너무나 많은 고통을 받아 왔어."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "じゃが、この外郭に住んでいる住民は侵食で大変苦しめられてきた。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But the people living here have suffered too much from the C.O.s."
L35_1.m_Talk_ENG = L36_1
L36_1 = "只是住在外城的居民，已經因為侵蝕而吃太多的苦。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่คนที่อาศัยอยู่ที่นี่ทุกข์ทรมานเพราะวัตถุคอร์รัปต์กันมากเกินไป"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng những người sống ở đây đã phải chịu đựng quá nhiều từ V.T.A.M"
L35_1.m_Talk_VTN = L36_1
L36_1 = "但生活在外城的居民们已经因为侵蚀承受了太多的痛苦。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber die Menschen, die hier in der Außenburg leben, haben zu sehr unter der Verderbnis gelitten."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Pour autant, les habitants de ce village ont déjà trop souffert des affres de la Corruption."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "BORDER_ACT1_STAGE3_START@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4500107
L36_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L36_1.m_Pos = "C"
L37_1 = "그러니 그들에겐 자네가 이름만 같은 다른 사람이었다고 설명할 걸세."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だから彼らにはお前さんを同名の別人だと説明するつもりじゃ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Thus, I'll explain to them that you are just someone who happens to have the same name."
L36_1.m_Talk_ENG = L37_1
L37_1 = "所以我會向他們解釋，你只是剛好同名同姓而已。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ดังนั้น ผมจะอธิบายกับพวกเขาว่าคุณแค่เป็นคนที่บังเอิญชื่อเหมือนกันเท่านั้น"
L36_1.m_Talk_THA = L37_1
L37_1 = "Vì vậy, tôi sẽ giải thích với họ rằng anh chỉ là một người trùng tên."
L36_1.m_Talk_VTN = L37_1
L37_1 = "所以我会告诉他们你跟他就是同名，并不是一个人。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Deshalb werde ich ihnen erklären, dass du nur jemand bist, der zufällig denselben Namen trägt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Pour ne pas ajouter à leur malheur, je vais leur dire que tu as simplement le même nom que Curian le Mousquetaire."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "BORDER_ACT1_STAGE3_START@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4500107
L37_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L37_1.m_Pos = "C"
L38_1 = "그들을 배려하는 마음이 있다면, 그런 헛소리는 더 이상 입 밖으로 내지 말게."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "彼らを思う心があるなら、もうそういうたわ言は言わないでおくれ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "If you care at all about these people I suggest you stop spouting such nonsense to them."
L37_1.m_Talk_ENG = L38_1
L38_1 = "若你還有一點憐憫之心，之後就不要說那些莫名其妙的話。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "และถ้าคุณใส่ใจคนพวกนี้ ผมขอแนะนำให้หยุดพ่นเรื่องไร้สาระใส่พวกเขาซะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nếu anh thực sự quan tâm đến những người này, tôi khuyên anh nên ngừng nói những điều vô nghĩa như vậy với họ."
L37_1.m_Talk_VTN = L38_1
L38_1 = "如果你想顾及他们的感受，那些胡言乱语就不要再说了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wenn dir diese Leute auch nur ein bisschen am Herzen liegen, schlage ich vor, dass du aufhörst, ihnen gegenüber solchem Unsinn zu erzählen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Si tu te soucies un tant soit peu du peuple, je te suggère de garder profil bas."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "BORDER_ACT1_STAGE3_START@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4500107
L38_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L38_1.m_Pos = "C"
L39_1 = "이 늙은이의 말을… 이해하겠나?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "この老人の言葉……わかるかな？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Do you understand... what this old man is asking of you?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "你有聽懂…我這個老頭子的話嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "คุณเข้าใจใช่มั้ย... สิ่งที่ชายแก่คนนี้ขอน่ะ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Anh có hiểu... ông già này đang yêu cầu anh điều gì không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "你就把这当做是……一个糟老头子的请求吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Verstehst du ... was dieser alte Mann von dir verlangt?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Tu comprends... ce que j'essaye de te dire ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "BORDER_ACT1_STAGE3_START@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4500107
L39_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "UNIT_IDLE"
L39_1.m_Face = L40_1
L39_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L39_1.m_Pos = "C"
L40_1 = "……알겠다. 그렇게 하지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……わかった。そうしよう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "...I understand. I'll do as you say."
L39_1.m_Talk_ENG = L40_1
L40_1 = "……有，我會照你說的辦。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ผมเข้าใจครับ ผมจะทำตามที่คุณบอก"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi hiểu. Tôi sẽ làm như ông nói."
L39_1.m_Talk_VTN = L40_1
L40_1 = "……明白了。那就照你说的做吧。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "... Ich verstehe. Ich werde tun, was du sagst."
L39_1.m_Talk_DEU = L40_1
L40_1 = "... Entendu. Je ferai ce que tu dis."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
