L40_1[L41_1] = true
L41_1 = {}
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4500107
L41_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L41_1.m_bWaitClick = false
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L42_1 = "L_D"
L41_1.m_Pos = L42_1
L42_1 = {}
L43_1 = "BORDER_ACT1_STAGE3_START@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4500107
L42_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "ONIL_BORDER_NULL_NAMED"
L43_1 = "R"
L42_1.m_Pos = L43_1
L43_1 = "그러면 이 자의 관리는 앞으로 엘라 님에게 부탁드리겠습니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それでは、この者の管理はこの先エラ様にお任せしましょう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Then, please keep an eye on this man, Captain Ella."
L42_1.m_Talk_ENG = L43_1
L43_1 = "那這個人之後就交由艾拉隊長負責囉。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถ้าอย่างนั้น ผมขอแต่งตั้งให้หัวหน้าเอลลาคอยจับตาดูชายคนนี้ไว้"
L42_1.m_Talk_THA = L43_1
L43_1 = "Vậy thì tôi sẽ chỉ định Đội trưởng Ella để mắt đến người đàn ông này."
L42_1.m_Talk_VTN = L43_1
L43_1 = "那你以后就归艾拉负责吧。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Behalten Sie diesen Mann bitte gut im Auge, Kommandantin Ella."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Et vous, capitaine Ella, veuillez garder un œil sur cet homme."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "BORDER_ACT1_STAGE3_START@43#Talk"
