L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4500107
L49_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L50_1 = "괜찮은 건가?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "大丈夫なのか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Are you sure you're all right?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "你還好嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แน่ใจใช่มั้ยว่าคุณไม่เป็นไร?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Cô chắc là cô ổn chứ?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "你还好吧？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Bist du sicher, dass es dir gut geht?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ça va aller, pour toi ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "BORDER_ACT1_STAGE3_START@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 4500107
L50_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "갑자기 무슨 소리지?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "いきなりなんだ？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "What do you mean?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "怎麼突然這麼問？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หมายความว่ายังไง?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ý anh là gì?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "嗯？什么意思？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Was meinst du?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Que veux-tu dire ?"
L50_1.m_Talk_FRA = L51_1
