L4_1 = "BORDER_ACT1_STAGE3_START@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4500107
L3_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_DESPAIR"
L3_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "아까부터 계속 아픈 걸 참는 기색이더군."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "さっきからずっと痛みを堪えている様子だった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You're trying not to show, but I can see that you're in pain."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我看你好像明明很痛卻一直在忍耐的樣子。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "คุณพยายามไม่แสดงออกมา แต่ผมดูนะว่าคุณกำลังเจ็บ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cô đang cố gắng không thể hiện, nhưng tôi có thể thấy rằng cô đang đau đớn."
L3_1.m_Talk_VTN = L4_1
L4_1 = "你似乎从刚才开始就一直在忍着疼痛。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Du versuchst, es nicht zu zeigen, aber ich kann sehen, dass du Schmerzen hast."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Tu as beau essayer de le cacher, je peux voir que tu as mal."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "BORDER_ACT1_STAGE3_START@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4500107
L4_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "옷이 젖고 있는데, 아무래도 피 같아서 말이야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "服が濡れているが、血なんじゃないか。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Also, your clothes are turning red, and I'm thinking that's probably blood."
L4_1.m_Talk_ENG = L5_1
L5_1 = "衣服都浸溼了，應該是在流血吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แถมเสื้อผ้าคุณก็กลายเป็นสีแดงแล้ว ผมว่านั่นน่าจะคือเลือดนะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Ngoài ra, quần áo của cô đang chuyển sang màu đỏ, và tôi nghĩ đó có thể là máu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "而且，你的衣服也被浸湿了，怎么看都是血。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Außerdem wird deine Kleidung langsam nass und ich denke, dass es wahrscheinlich Blut ist."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Et puis cette tâche sur ton vêtement... difficile d'y voir autre chose que du sang."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "BORDER_ACT1_STAGE3_START@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4500107
L5_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "복부의 상처가 터진 것뿐이야."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "腹の傷口が開いただけ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "It's just seepage from my abdomen wound."
L5_1.m_Talk_ENG = L6_1
L6_1 = "只是腹部的傷口裂開而已。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แค่เลือดซึมจากแผลที่ท้องน่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nó chỉ là phần bị rỉ ra từ vết thương ở bụng tôi thôi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "腹部的伤口裂开了而已。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Es ist nur so, dass meine Wunde im Bauch aufgerissen ist."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ce n'est rien, simplement ma blessure à l'abdomen qui s'est rouverte."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "BORDER_ACT1_STAGE3_START@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4500107
L6_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_SURPRISE"
L6_1.m_Face = L7_1
L6_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L7_1 = "R"
L6_1.m_Pos = L7_1
L7_1 = "혹시 날 구하다가 다친 건가?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "もしかして私を助けてくれた時に怪我したのか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Did that happen while you were saving me?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "是救我的時候受傷的嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แผลนั่นได้มาตอนที่ช่วยผมรึเปล่า?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Có phải điều đó đã xảy ra trong khi cô đang cứu tôi?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "是为了救我才受的伤吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ist das passiert, als du mich gerettet hast?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu t'es fait ça lorsque tu m'as secouru ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "BORDER_ACT1_STAGE3_START@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500107
L7_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L8_1 = "L"
L7_1.m_Pos = L8_1
L8_1 = "신경 쓸 것 없어. 체질 문제 때문에 회복이 평소보다 더딜 뿐이니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "気にすることない。体質の問題でいつもより回復が遅いだけだから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Don't worry about it. Due to my physical constitution, the recovery is slower than usual."
L7_1.m_Talk_ENG = L8_1
L8_1 = "沒事，只是因爲體質的關係，恢復得比平時慢而已。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ไม่ต้องห่วงหรอก เวลาฟื้นตัวฉันจะเคลื่อนไหวช้ากว่าปกติน่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đừng lo lắng về nó. Tôi chỉ hồi phục chậm một cách bất thường."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你不用在意。只是体质问题，恢复得比一般人慢而已。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Mach dir darüber keine Sorgen. Aufgrund meiner körperlichen Verfassung verläuft die Genesung langsamer als gewöhnlich."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ne t'inquiète pas, je vais bien. C'est juste que je récupère moins vite que la moyenne."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "BORDER_ACT1_STAGE3_START@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4500107
L8_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_IDLE"
L8_1.m_Face = L9_1
L8_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L9_1 = "R"
L8_1.m_Pos = L9_1
L9_1 = "그렇군. 수술을 할 수 있을 정도라면 나보다 자기 몸은 더 잘 알겠지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "そうか。手術ができるくらいなら、私より自分の体についてよく知っているんだろう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I see. Being a surgeon and all, I'm sure you know more about your body that I do about mine."
L8_1.m_Talk_ENG = L9_1
L9_1 = "原來如此，既然你能夠動手術，那應該比我更清楚自己的身體狀況吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อย่างนี้เอง ทั้งเรื่องเป็นศัลยแพทย์และอะไรต่อมิอะไร ผมว่าคุณคงรู้จักร่างกายของคุณดีกว่าที่ผมรู้จักร่างกายตัวเอง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi hiểu rồi. Là một bác sĩ phẫu thuật, nên hẳn cô hiểu về cơ thể của mình nhiều hơn tôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "原来如此。能做手术的话，你应该比我更了解自己的身体。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich verstehe. Als Ärztin weißt du sicher mehr über deinen Körper als ich über meinen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je vois. À voir comme tu m'as opéré, je suppose que tu en sais plus que moi sur le corps humain."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "BORDER_ACT1_STAGE3_START@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500107
L9_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "당신이야말로 수술 때 피를 많이 흘렸어. 영양 보충이 필요할 거야."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あなたこそ手術中の出血が酷かった。栄養の補給が必要ね。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You in particular lost a lot of blood during the surgery. You'll need nutrients."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你才是剛動手術時流了很多血，應該需要補充營養。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คุณเสียเลือดไปเยอะระหว่างผ่าตัดนะ คุณต้องการสารอาหาร"
L9_1.m_Talk_THA = L10_1
L10_1 = "Anh đặc biệt mất rất nhiều máu trong quá trình phẫu thuật. Anh sẽ cần chất dinh dưỡng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "先关心关心你自己吧。你手术时流了很多血，需要补充营养。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Du hast während der Operation viel Blut verloren. Du brauchst also Nährstoffe."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tu ferais mieux de reposer. Tu as perdu beaucoup de sang pendant l'opération."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "BORDER_ACT1_STAGE3_START@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4500107
L10_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L11_1 = "R"
L10_1.m_Pos = L11_1
L11_1 = "듣고 보니……. 허기가 지는군. 배에 구멍이 뚫린 것 같아."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そういえば……腹が空いたな。腹に穴が開いているようだ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Now that you mention it... I do feel hungry. It's as if there's a hole in my stomach."
L10_1.m_Talk_ENG = L11_1
L11_1 = "聽你這麼一説……真的有飢餓感，肚子好像破個洞一樣。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จะว่าไป... ผมก็หิวอยู่นะ อย่างกับมีรูอยู่ในท้องเลย"
L10_1.m_Talk_THA = L11_1
L11_1 = "Cô nói thì... tôi cảm thấy đói rồi. Như thể có một cái lỗ trong bụng tôi vậy."
L10_1.m_Talk_VTN = L11_1
L11_1 = "听你这么一说……确实感觉饿了。肚子上好像破了个洞似的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Jetzt, wo du es erwähnst ... habe ich tatsächlich Hunger. Es ist, als ob da ein Loch in meinem Magen wäre."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Maintenant que tu en parles... j'ai une de ces faims ! C'est comme si j'avais un trou béant dans l'estomac."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "BORDER_ACT1_STAGE3_START@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4500107
L11_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "당신도 자기 몸을 참 잘 아는 것 같네. 혹시 감자 알러지 있어?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あなたも自身の体についてよくわかっているみたいだね。ジャガイモアレルギーはある？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Seem to know a bit about your body as well. Are you allergic to potatoes by any chance?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "看來你也很清楚自己的身體，你會對馬鈴薯過敏嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณก็ดูจะรู้เรื่องร่างกายอยู่บ้างนะ คุณแพ้มันฝรั่งรึเปล่าล่ะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Dường như anh cũng biết một chút về cơ thể của mình. Anh có bị dị ứng với khoai tây không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "你也真是很了解自己的身体啊。你对土豆过敏吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du scheinst deinen Körper sehr gut zu kennen. Bist du vielleicht allergisch gegen Kartoffeln?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je vois que tu es à l'écoute de ton corps, toi aussi. Tu n'es pas allergique aux pommes de terre ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "BORDER_ACT1_STAGE3_START@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500107
L12_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L13_1 = "R"
L12_1.m_Pos = L13_1
L13_1 = "음? 딱히 그런 건 없다만."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "む？　そんなものはないが。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Hmm? I don't think so?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯？不會。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อืมม? ผมว่าไม่นะ มั้ง?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Hmm? Tôi không nghĩ vậy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "呃，不过敏。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Hmm? Ich glaube nicht?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Hmm ? Je ne crois pas, non."
L12_1.m_Talk_FRA = L13_1
