L18_1 = "BORDER_ACT1_STAGE3_START@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4500107
L17_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_LAUGH"
L17_1.m_Face = L18_1
L17_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L17_1.m_Pos = "C"
L18_1 = "대접해 줘서 고맙다. 감자로 이런 맛을 낼 수도 있군."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "もてなしてくれてありがとう。ジャガイモでこんな味も出せるんだな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Thanks for the hospitality. I didn't know potatoes could taste this good."
L17_1.m_Talk_ENG = L18_1
L18_1 = "謝謝你的招待，沒想到馬鈴薯可以做出這種味道。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ขอบคุณในความเอื้อเฟื้อนะ ผมไม่เคยรู้เลยว่ามันฝรั่งจะอร่อยขนาดนี้"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cảm ơn đã thiết đãi. Tôi không biết khoai tây có thể ngon thế này."
L17_1.m_Talk_VTN = L18_1
L18_1 = "啊……多谢款待。原来土豆还能做出这种美味。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Danke für die Gastfreundschaft. Ich wusste nicht, dass Kartoffeln so gut schmecken können."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Merci pour ton hospitalité. C'est la meilleure pomme de terre que j'ai jamais mangé."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "BORDER_ACT1_STAGE3_START@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4500107
L18_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "금방 물릴 테니 각오해 두는 게 좋아."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "すぐ飽きると思うから覚悟しておくといいね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "You'll get sick of them soon enough."
L18_1.m_Talk_ENG = L19_1
L19_1 = "勸你最好做好心理准備，你很快就會吃膩的。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เดี๋ยวคุณก็เบื่อแล้วล่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Anh sẽ phát ngán vì chúng sớm thôi."
L18_1.m_Talk_VTN = L19_1
L19_1 = "很快你就会吃腻的，做好心理准备吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Du wirst sie schon noch früh genug satt haben."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Crois-moi, on finit par s'en lasser."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "BORDER_ACT1_STAGE3_START@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4500107
L19_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "여기서 기르는 작물은 감자나 칡 정도니까."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "ここで育てている作物はジャガイモと葛くらいだから。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "All that grows around here is potatoes and arrowroot."
L19_1.m_Talk_ENG = L20_1
L20_1 = "因為這裡只能種馬鈴薯和葛藤。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ที่ขึ้นแถวนี้มีแต่มันฝรั่งกับเท้ายายม่อม"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tất cả những gì mọc quanh đây là khoai tây và dong riềng."
L19_1.m_Talk_VTN = L20_1
L20_1 = "这里能种植的农作物就只有土豆和葛根了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Alles, was hier wächst, sind Kartoffeln und Pfeilwurz."
L19_1.m_Talk_DEU = L20_1
L20_1 = "C'est tout ce qu'on a, dans le coin. Des pommes de terre et des marantes."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "BORDER_ACT1_STAGE3_START@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4500107
L20_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_IDLE"
L20_1.m_Face = L21_1
L20_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L20_1.m_Pos = "C"
L21_1 = "내가 여기 계속 머물러도 괜찮겠나?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "私がずっとここにいても大丈夫なのか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Are you sure it's okay for me to stay here?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "我可以繼續留在這裡嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คุณแน่ใจเหรอว่าผมพักอยู่นี่ไม่เป็นไรจริงๆ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô có chắc là tôi ở đây ổn không?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "咳……所以，我继续留在这里也没关系吗？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wäre es in Ordnung, wenn ich hier bleiben würde?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Ça te dérange vraiment pas, que je reste ici ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "BORDER_ACT1_STAGE3_START@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4500107
L21_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "자기를 큐리안이라고 믿는 얼뜨기 한 명도 챙겨 주지 못할 만큼 인심 박한 곳은 아니야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "自分がキュリアンだと信じてるバカ一人の面倒も見れないほど、ここは薄情なところじゃない。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "We're not going to kick you out just because you're some idiot who believes he's Curian."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這裡可不是一個沒有人情味的地方，冷漠到連一個自稱是庫里安的傻瓜都無法包容。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เราไม่ไล่คุณออกไปแค่เพราะคุณเป็นคนโง่ที่เชื่อว่าตัวเองคือคิวเรี่ยนหรอกนะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chúng tôi sẽ không đuổi anh ra ngoài chỉ vì anh là một thằng ngốc tin rằng mình là Curian."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我们这儿可不是什么人情淡薄的地方，不至于连个认为自己是奎里安的笨蛋都照顾不了。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wir werden dich nicht rausschmeißen, nur weil du ein Idiot bist, der glaubt, er sei Curian."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ce n'est pas parce que tu n'as pas toute ta tête et que tu prétends être Curian qu'on va te chasser comme des sauvages."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "BORDER_ACT1_STAGE3_START@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4500107
L22_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L22_1.m_Pos = "C"
L23_1 = "고맙군. 그럼 염치 불구하고 몸이 회복될 때까지만 신세를 지기로 하지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ありがたい。それでは遠慮なく体が回復するまではお世話になろう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I appreciate it. Then I'll stay just long enough to recover."
L22_1.m_Talk_ENG = L23_1
L23_1 = "謝謝，那我就不客氣了，我會在這裡待到身體恢復爲止。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ขอบคุณมากๆ เลยนะ ถ้าอย่างนั้นผมคงอยู่นานขึ้นอีกนิด จะได้ฟื้นตัว"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi rất cảm kích. Thế thì tôi sẽ ở lại đến khi hồi phục."
L22_1.m_Talk_VTN = L23_1
L23_1 = "非常感谢，那么在身体康复之前，都要给你们添麻烦了。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich weiß das zu schätzen. Dann bleibe ich, bis ich mich erholt habe."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Merci. Je prendrai congé dès que je serai sur pied."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
