L25_1 = "BORDER_ACT1_STAGE3_START@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4500107
L24_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L25_1 = "L"
L24_1.m_Pos = L25_1
L25_1 = "그리고 이거 받아."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "それから、これ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Oh, and take these."
L24_1.m_Talk_ENG = L25_1
L25_1 = "還有，這給你。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "อ้อ แล้วก็เอานี่ไปด้วย"
L24_1.m_Talk_THA = L25_1
L25_1 = "À, cầm lấy mấy thứ này."
L24_1.m_Talk_VTN = L25_1
L25_1 = "还有，给你这个。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh, und nimm diese."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Oh, et prends ceci."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "BORDER_ACT1_STAGE3_START@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4500107
L25_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_SURPRISE"
L25_1.m_Face = L26_1
L25_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L26_1 = "R"
L25_1.m_Pos = L26_1
L26_1 = "뭐지, 이건? 나뭇가지와 나이프…?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "これは何だ？　木の枝とナイフ……？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Huh? A twig and a knife...?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "這是什麼？樹枝和小刀…？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เอ๋? กิ่งไม้กับมีดเหรอ...?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Hả? Một cành cây và một con dao...?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "这是什么？！树枝和小刀……？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Huch? Ein Zweig und ein Messer ...?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Une branche et un couteau ? Mais pourquoi faire ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "BORDER_ACT1_STAGE3_START@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4500107
L26_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L27_1 = "L"
L26_1.m_Pos = L27_1
L27_1 = "배를 채웠으면 밥값을 해야지. 누워 있는 동안 같이 화살이나 깎아 줘."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "食べたらそれに見合う働きをしないとね。療養中は一緒に矢を作ってちょうだい。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "\"He who does not work, neither shall he eat\". Make some arrows with me while you lie in bed."
L26_1.m_Talk_ENG = L27_1
L27_1 = "天下沒有白吃的午餐，躺著沒事就幫我削箭吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "\"คนที่ไม่ทำงานก็ไม่ควรได้ทานอะไรเหมือนกัน\" ระหว่างนอนบนเตียงก็มาทำธนูกับฉันเถอะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "\"Xã hội này có làm thì mới có ăn \". Làm vài mũi tên với tôi trong khi anh nằm trên giường đi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "吃饱了就要付饭钱。躺着养伤期间一起削些箭吧。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "„Wer nicht arbeitet, der soll auch nicht essen.“ Schnitze mit mir ein paar Pfeile, während du im Bett liegst."
L26_1.m_Talk_DEU = L27_1
L27_1 = "« Qui dort dîne ». Tu as beau être alité, tu peux toujours m'aider à faire des flèches."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
