L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4500107
L29_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_IDLE"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L29_1.m_Pos = "C"
L30_1 = "그런데 국경수비대라는 건 어떤 조직이지? 처음 듣는 이름이었어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ところで国境守備隊とはどんな組織なんだ？　初めて聞いたんだが。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "By the way, what's the \"Border Guards\"? I've never heard of this organization before."
L29_1.m_Talk_ENG = L30_1
L30_1 = "不過國境護衛隊是什麼組織？我第一次聽説這個組織。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ว่าแต่ \"องครักษ์พิทักษ์ชายแดน\" คืออะไรเหรอ? ผมไม่เคยได้ยินชื่อองค์กรนี้เลย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhân tiện, \"Cảnh vệ Biên phòng\" là gì? Tôi chưa bao giờ nghe nói về tổ chức này trước đây."
L29_1.m_Talk_VTN = L30_1
L30_1 = "咳……所以说，边境护卫队到底是什么组织？我还是第一次听说呢。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Übrigens, was ist eigentlich dieser „Grenzschutz“? Ich habe noch nie von dieser Organisation gehört."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Au fait, qui sont ces fameux « garde-frontières » ? Je n'ai jamais entendu parler d'eux auparavant."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
