L32_1 = "BORDER_ACT1_STAGE3_START@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4500107
L31_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "총사대가 전멸하고 왕의 마지막 직계마저 디어루트에서 전사하면서, 노르드나빅은 국가 기능을 상실했어."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "銃士隊が全滅して王の最後の直系もディアルートで戦死した後、ノルドナビックは国家としての機能を失ってね。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Nordnavik ceased to function when the Musketeer Division got obliterated and the last of the king's descendants was killed in battle in Deer Root."
L31_1.m_Talk_ENG = L32_1
L32_1 = "射擊隊全軍覆沒後，國王的最後一個嫡系也戰死在迪魯特，諾爾德萊比於是失去國家的功能。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "พอหน่วยแม่นปืนถูกทำลายสิ้นซากนอร์ดเนวิกก็จบสิ้น\nและทายาทคนสุดท้ายของราชาก็ถูกฆ่าตายในศึกที่เดียร์รูต"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nordnavik ngừng hoạt động khi Sư đoàn Thiện xạ bị xóa sổ và hậu duệ cuối cùng của nhà vua bị giết trong trận chiến ở Rễ Hươu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "随着火枪手队的全军覆没、王室最后的直系血脉在迪尔鲁特战死，诺德纳维克丧失了国家的职能。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nordnavik funktionierte nicht mehr, als die Musketier-Division vernichtet wurde und der letzte Nachkomme des Königs in der Schlacht in Hirschwurzel getötet wurde."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Après la défaite des Mousquetaires et la disparition au combat du dernier roi à Haute-Ramure, Nordnavik a cessé de fonctionner en tant que nation."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "BORDER_ACT1_STAGE3_START@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4500107
L32_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "남은 귀족들은 국가 재건단을 세우고 빈 왕좌를 대신해 군을 재편성했지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "残った貴族は国家再建団を立ち上げ、不在の王の代わりに軍を再編成した。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "The remaining nobles formed the National Reconstruction Alliance and reorganized the army on behalf of the empty throne."
L32_1.m_Talk_ENG = L33_1
L33_1 = "其餘的貴族設立國家重建委員會，代替空著的王座重新組織軍隊。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ชนชั้นสูงที่เหลืออยู่ก็ก่อตั้งพันธมิตรฟื้นฟูชาติขึ้นมา แล้วก็สร้างกองทัพขึ้นมาใหม่ในนามของบัลลังก์ที่ว่างเปล่า"
L32_1.m_Talk_THA = L33_1
L33_1 = "Những quý tộc còn lại đã thành lập Liên Minh Tái thiết Quốc gia và tổ chức lại quân đội thay cho ngai vàng trống rỗng."
L32_1.m_Talk_VTN = L33_1
L33_1 = "剩下的贵族们建立了国家重建同盟，代替空着的王位整编了军队。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Die verbleibenden Adligen gründeten die Nationale Wiederaufbaustiftung und organisierten die Armee im Namen des leeren Throns neu."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Les nobles ayant survécu au massacre ont formé l'Alliance de reconstruction du pays, et ont fait de leur mieux pour reconstituer une armée en l'absence de souverain."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "BORDER_ACT1_STAGE3_START@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4500107
L33_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "왕립 국경수비대도 그 중 하나지. 말 그대로 국경을 지키기 위해 만들어진 조직이야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "王立国境守備隊もその一つよ。言葉どおり、国境を守るために作られた組織なんだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "The Royal Border Guards is one of those organizations. As the name suggests, it was created to protect this country's borders."
L33_1.m_Talk_ENG = L34_1
L34_1 = "皇家國境護衛隊也是其中之一，簡單來說，就是爲保衛國境而成立的組織。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "องครักษ์พิทักษ์ชายแดนก็เป็นหนึ่งในองค์กรพวกนั้น ซึ่งหน้าที่เหมือนชื่อนั่นแหละ ถูกก่อตั้งขึ้นมาเพื่อปกป้องชายแดนประเทศ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cảnh vệ Biên phòng Hoàng gia là một trong những tổ chức đó. Đúng như tên gọi, nó được tạo ra để bảo vệ biên giới của đất nước này."
L33_1.m_Talk_VTN = L34_1
L34_1 = "皇家边境护卫队也是其中之一。顾名思义，就是为守卫边境而设立的组织。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Der Königliche Grenzschutz ist eine dieser Organisationen. Wie der Name schon sagt, wurde er geschaffen, um die Grenzen dieses Landes zu schützen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Les garde-frontières royaux font partie des nouvelles armées constituées. Comme son nom l'indique, cette division a été créée pour protéger les frontières du pays."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "BORDER_ACT1_STAGE3_START@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4500107
L34_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L34_1.m_Pos = "C"
L35_1 = "하지만 자네들은 병영도 없이 마을 주민들과 함께 지내는 것 같더군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "だが、君たちは兵営もなく村の住民と一緒に過ごしているようだったが。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "But it seems as if you live with the villagers and without any barracks?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "可是你們好像連兵營都沒有，而是和村民住在一起。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แต่ดูเหมือนคุณจะอยู่กับชาวบ้านโดยไม่มีค่ายทหารเลยไม่ใช่เหรอ?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nhưng có vẻ như cô sống với dân làng và không có bất kỳ doanh trại nào?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "可是我看你们好像连兵营都没有，就是跟村民们一起生活。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Aber du scheinst mit den Dorfbewohnern zusammenzuleben, ohne überhaupt eine Kaserne zu haben."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Mais pourquoi vivez-vous ici, avec les villageois ? Et non dans une caserne ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "BORDER_ACT1_STAGE3_START@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4500107
L35_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "말만 왕립이고 근방 거주민들을 데려다가 최소한의 훈련만 시키는 게 실상이니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "王立は名前だけで、周辺の住民を連れてきて最低限の訓練だけしてるのが実状でね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "The \"royal\" part is merely symbolic, and the truth is that it is made up of villagers with only basic training."
L35_1.m_Talk_ENG = L36_1
L36_1 = "表面上說是皇家，但其實只是把附近居民聚集在這裡，做一些最基本的訓練而已。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "คำว่า “หลวง” ก็แค่สัญลักษณ์น่ะ และความจริงก็คือองค์กรนั่นมีแต่ชาวบ้านที่ฝึกพื้นฐานมาเท่านั้น"
L35_1.m_Talk_THA = L36_1
L36_1 = "Phần \"hoàng gia\" chỉ mang tính tượng trưng, sự thật là nó được tạo ra từ dân làng chỉ được đào tạo cơ bản thôi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "说是皇家，只不过是好听而已，其实就是把一些附近的居民召集过来，进行最基本的训练。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Der „königliche“ Teil ist lediglich symbolisch und die Wahrheit ist, dass er aus Dorfbewohnern besteht, die nur über eine Grundausbildung verfügen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Le terme « royal » est purement symbolique. N'importe qui en état de se battre peut rejoindre les garde-frontières."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "BORDER_ACT1_STAGE3_START@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4500107
L36_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "내 부대원들도 대부분 자기 고향을 지키겠다고 모인 사람들이야."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私の部隊員もほとんどが故郷を守ろうと集まった人たちよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Most of my troops are villagers who gathered together to protect their homes, too."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我的隊員之所以會在這裡，大部分也都是因為想保護自己的家鄉。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "กองกำลังส่วนใหญ่ของฉันก็เป็นชาวบ้านที่มารวมตัวกันเพื่อปกป้องบ้านตัวเอง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hầu hết quân đội của tôi là dân làng, cũng là những người tập hợp lại để bảo vệ ngôi nhà của họ."
L36_1.m_Talk_VTN = L37_1
L37_1 = "我们部队的成员大部分也都是为保卫自己的家乡才召集起来的人。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Die meisten meiner Truppen sind Dorfbewohner, die sich ebenfalls versammelt haben, um ihre Häuser zu schützen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "La plupart des soldats qui se battent ici sont des villageois qui cherchent à protéger leur maison."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "BORDER_ACT1_STAGE3_START@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4500107
L37_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "노르드나빅에 그렇게 만들어진 국경수비대만 백 군데가 넘어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そうやって作られた国境守備隊だけでも、ノルドナビックには百以上もある。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "There should be more than a hundred or so Border Guards all across Nordnavik."
L37_1.m_Talk_ENG = L38_1
L38_1 = "在諾爾德萊比，這樣的組織超過一百個以上。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "องครักษ์พิทักษ์ชายแดนทั่วนอร์ดเนวิกน่าจะมีประมาณร้อยคนหน่อยๆ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Có hơn một trăm Cảnh vệ Biên phòng trên khắp Nordnavik."
L37_1.m_Talk_VTN = L38_1
L38_1 = "诺德纳维克有一百多个这样组建起来的边境护卫队。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "In ganz Nordnavik sollte es mehr als hundert Grenzschutzbeamte geben."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Des divisons de garde-frontières comme celle-ci, Nordnavik en compte plus d'une centaine."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "BORDER_ACT1_STAGE3_START@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4500107
L38_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "급하게 숫자만 늘리다 보니 규모가 너무 커져서, 재건단도 지원은 포기한 지 오래지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "急いで数だけを増やしてたら規模が大きくなりすぎて、再建団もとっくに支援を諦めている。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "However, the Alliance abandoned giving us any support since long ago. The scale grew out of control when they focused on just creating as many units as possible."
L38_1.m_Talk_ENG = L39_1
L39_1 = "急著擴充數量的結果，就是規模太龐大，重建委員會也早已放棄支援。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ถึงอย่างนั้น พวกพันธมิตรก็เลิกสนับสนุนอะไรเรามานานแล้ว จำนวนเริ่มมากเกินควบคุมก็ตอนที่พวกเขาเอาแต่เน้นเรื่องเพิ่มหน่วยรบให้มากที่สุด"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tuy nhiên, Liên Minh đã từ bỏ việc hỗ trợ chúng tôi từ lâu rồi. Quy mô đã mất kiểm soát khi họ chỉ tập trung vào việc tạo ra càng nhiều đơn vị càng tốt."
L38_1.m_Talk_VTN = L39_1
L39_1 = "最后因为数量增加得太快、规模变得太大，同盟早就放弃支援了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Die Wiederaufbaustiftung hat jedoch schon vor langer Zeit aufgegeben, uns zu unterstützen. Das Ausmaß geriet außer Kontrolle, als man sich darauf konzentrierte, so viele Einheiten wie möglich zu schaffen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais nos effectifs ont augmenté plus vite que prévu, trop vite pour que l'Alliance puisse continuer de nous apporter son soutien logistique."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "BORDER_ACT1_STAGE3_START@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4500107
L39_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "그러니 민간인들과의 공생은 필수야. 사람들을 보호해 주고 그 대가로 물자를 받는 거지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "だから民間人との共生は必須。人々を守る代わりに物資をもらうんだ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "That's why coexisting with the villagers is crucial. We protect them, and in return we get supplies."
L39_1.m_Talk_ENG = L40_1
L40_1 = "因此和百姓們共生是必要的，我們保護他們，他們則提供物資作為回報。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เพราะแบบนั้นการอยู่ร่วมกับชาวบ้านเลยสำคัญ เราปกป้องพวกเขา พวกเขาให้เสบียงเรา"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đó là lý do tại sao cùng tồn tại với dân làng là rất quan trọng. Chúng tôi bảo vệ họ, và đổi lại, chúng tôi nhận được vật tư."
L39_1.m_Talk_VTN = L40_1
L40_1 = "这就是我们必须和居民们和平共处的原因了。我们保护人们，作为回报，从居民那里拿取物资。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Deshalb ist das Zusammenleben mit den Dorfbewohnern von entscheidender Bedeutung. Wir beschützen sie und bekommen im Gegenzug Vorräte."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Voilà pourquoi nous devons collaborer avec les villageois. Nous leur apportons la protection et eux, le pain quotidien."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "BORDER_ACT1_STAGE3_START@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4500107
L40_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_LAUGH"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "가끔은 텃밭일도 도와 주고 말이야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "たまに畑仕事も手伝ったりしてね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We help them with farming as well sometimes."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我們有時候也會幫忙種田。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "บางครั้งเราก็ช่วยพวกเขาทำไร่ด้วย"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đôi khi chúng tôi cũng giúp họ làm ruộng."
L40_1.m_Talk_VTN = L41_1
L41_1 = "当然，偶尔也会帮居民做做农活什么的。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Manchmal helfen wir ihnen auch bei der Arbeit in der Landwirtschaft."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Il nous arrive parfois de les aider pour les récoltes."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "BORDER_ACT1_STAGE3_START@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4500107
L41_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_PRIDE"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L41_1.m_Pos = "C"
L42_1 = "실력을 보니 요리도 자주 도왔던 모양이군."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "実力を見るかぎり、料理も頻繁に手伝っていたみたいだな。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Judging by your cooking skills, you helped out a lot in the kitchen, no?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "根據剛剛的料理，你應該也蠻常幫忙做菜的吧？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ดูจากฝีมือทำอาหารแล้วนี่ คุณคงช่วยงานในครัวเยอะเลยสินะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nhìn khả năng của cô chắc là cô đã giúp việc bếp núc nhiều, phải không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "按照你的厨艺水平，好像也经常帮忙做饭啊？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Den Kochkünsten nach zu urteilen, hast du doch viel in der Küche mitgeholfen, nicht wahr?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "À en juger par tes talents culinaires, j'imagine que tu es aussi bien présente aux fourneaux ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "BORDER_ACT1_STAGE3_START@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4500107
L42_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_IDLE"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "재료라고 해 봐야 감자랑 도시에서 구한 향신료 조금뿐이지만."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "材料といってもジャガイモと都市で買った香辛料少々が全てだけど。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You can't really call it cooking if it's only potatoes and some spices we got from the city."
L42_1.m_Talk_ENG = L43_1
L43_1 = "材料就只有馬鈴薯，和一點點在城裡弄到的香料而已。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "จะเรียกว่าทำอาหารก็คงไม่ได้หรอก ถ้ามีแค่มันฝรั่งกับเครื่องเทศไม่กี่อย่างที่เราหาได้จากเมืองนี้น่ะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Anh thực sự không thể gọi nó là nấu ăn nếu chỉ có khoai tây và chút gia vị chúng tôi lấy từ thành phố."
L42_1.m_Talk_VTN = L43_1
L43_1 = "就只有土豆跟在城里买的一点香辛料，这也算不上烹饪吧。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Man kann es nicht wirklich Kochen nennen, wenn wir nur Kartoffeln und ein paar Gewürze aus der Stadt bekommen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ce n'est rien d'autre que quelques pommes de terre et des épices de la ville, on ne peut pas vraiment appeler ça de la cuisine."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "BORDER_ACT1_STAGE3_START@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4500107
L43_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_IDLE"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L43_1.m_Pos = "C"
L44_1 = "여긴 물자가 많이 부족한 편인가?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ここの物資はだいぶ足りない方なのか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Is there a shortage of supplies here?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "這裡的物資非常缺乏嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ที่นี่ขาดแคลนเสบียงเหรอ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Phải chăng ở đây đang thiếu vật tư?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "呃，这里物资很紧缺吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Gibt es hier einen Mangel an Vorräten?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Y'a-t-il une pénurie de fournitures ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "BORDER_ACT1_STAGE3_START@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4500107
L44_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "장비가 고장나도 새로 보급 받지 못해서 놔두는 상황이야. 식량도 자급자족하는 상황이고."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "装備が壊れても新しく補給してもらえなくてそのまま放置している状況よ。食糧も自給自足だし。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Broken equipment is practically abandoned as we don't have the supplies to fix them. And what food is produced is used to feed the village."
L44_1.m_Talk_ENG = L45_1
L45_1 = "設備壞掉也不會補新的，就只能扔在一邊，糧食也都是自給自足。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "พวกอุปกรณ์ที่พังก็ต้องทิ้งไปเพราะเราไม่มีอะไรมาซ่อมน่ะ อาหารก็ทำแค่เลี้ยงปากท้องชาวบ้านเท่านั้น"
L44_1.m_Talk_THA = L45_1
L45_1 = "Thiết bị bị hỏng sẽ bị vứt đi vì chúng tôi không có vật tư để sửa chữa chúng. Và thực phẩm được sử dụng để nuôi sống ngôi làng."
L44_1.m_Talk_VTN = L45_1
L45_1 = "装备出故障了，没有新的补给修不了，就只能那么放着，粮食也是靠自给自足。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Kaputte Ausrüstung kann nicht durch neue ersetzt werden und wir verfügen nicht über die Vorräte, um sie zu reparieren. Und die produzierten Lebensmittel werden zur Ernährung des Dorfes verwendet."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Les équipements inutilisables ont été laissés à l'abandon, et nous n'avons pas de quoi les réparer. Toutes les récoltes sont utilisées pour nourrir les bouches du village."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "BORDER_ACT1_STAGE3_START@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4500107
L45_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "이만하면 충분한 대답이 됐어?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "このくらいで答えになったかな？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Does that answer your question?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "你還有什麼問題嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "นั่นตอบคำถามมั้ยนะ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Câu trả lời đó có đáp ứng được câu hỏi của anh không?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "这样足够回答你的问题了吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Beantwortet das deine Frage?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Est-ce que ça répond à ta question ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "BORDER_ACT1_STAGE3_START@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4500107
L46_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
