L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L46_1.m_Pos = "C"
L47_1 = "그 고장 났다는 장비, 내가 좀 확인해 봐도 되겠나?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "その壊れたという装備、私が確認してみてもいいか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "The broken equipment you mentioned. Would you mind if I take a look at them?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我可以看一下壞掉的設備嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อุปกรณ์ที่พังที่ว่านี่ ผมขอดูหน่อยได้มั้ย?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Mấy thiết bị hỏng mà cô nói ấy. Có phiền không nếu tôi xem qua chúng?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "那个出故障的装备，我能看看吗……？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Die kaputte Ausrüstung, die du erwähnt hast. Würde es dir etwas ausmachen, wenn ich sie mir einmal ansehe?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ces équipements... est-ce que je pourrais y jeter un œil ?"
L46_1.m_Talk_FRA = L47_1
