L3_1 = "BORDER_ACT1_STAGE3_START@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4500107
L2_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L2_1.m_bWaitClick = true
