L3_1 = "WATT_BORDER_NULL_ARMED"
L2_1.m_CharStrID = L3_1
L3_1 = "R"
L2_1.m_Pos = L3_1
L3_1 = "엘라 대장님? 저 사람이 대체 여기서 뭘 하고 있는 거죠?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "エラ隊長？　あいつ、ここで一体何をしているんですか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Captain Ella? What's that person doing here?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "艾拉隊長？那個人到底在這裡做什麼？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "หัวหน้าเอลลา? คนนั้นเขามาทำอะไรที่นี่น่ะครับ?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Đội trưởng Ella? Người đó làm gì ở đây?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "艾拉队长？那个人究竟在这里做什么呢？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Kommandantin Ella? Was macht denn diese Person hier?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Capitaine Ella ? Que fait cette personne ici avec vous ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "BORDER_ACT1_STAGE3_START@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4500107
L3_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "보다시피 1년 전 고장난 쐐기 대포를 고치고 있어."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "見てのとおり、1年前に壊れたくさび大砲を直している。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "As you can see, he's fixing the Ironshot Cannon that broke last year."
L3_1.m_Talk_ENG = L4_1
L4_1 = "就像你眼睛看到的，他正在修理一年前壞掉的楔子大砲。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ก็อย่างที่เห็นแหละ เขากำลังซ่อมปืนใหญ่กระสุนเหล็กที่พังไปปีก่อน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Như anh có thể thấy đấy, anh ấy đang sửa khẩu Đại bác Ironshot bị hỏng năm ngoái."
L3_1.m_Talk_VTN = L4_1
L4_1 = "如你所见，他在修理去年出故障的那门楔子大炮。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wie du sehen kannst, repariert er die Keilkanone, die letztes Jahr kaputt gegangen ist."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Comme tu peux le voir, il est en train de réparer le canon Salvefer qui a rendu l'âme l'année dernière."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "BORDER_ACT1_STAGE3_START@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4500107
L4_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L5_1 = "L"
L4_1.m_Pos = L5_1
L5_1 = "자기 목숨을 구해 준 답례를 하고 싶다네."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "自分の命を救ってくれた恩返しをしたいんだそうだ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "He said he wants to give something back for saving his life."
L4_1.m_Talk_ENG = L5_1
L5_1 = "他想報答救命恩人。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เขาบอกว่าอยากตอบแทนที่เราช่วยชีวิตเขาไว้"
L4_1.m_Talk_THA = L5_1
L5_1 = "Anh ấy nói rằng anh ấy muốn trả ơn cứu mạng."
L4_1.m_Talk_VTN = L5_1
L5_1 = "说是想报答我的救命之恩。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Er möchte sich dafür revanchieren, dass sein Leben gerettet wurde."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Il voulait faire un geste pour nous remercier de lui avoir sauvé la vie."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "BORDER_ACT1_STAGE3_START@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4500107
L5_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "WATT_BORDER_NULL_ARMED"
L5_1.m_CharStrID = L6_1
L6_1 = "R"
L5_1.m_Pos = L6_1
L6_1 = "하지만 신분도 불분명한 외부인에게 중요한 장비를 맡기는 건 좀……"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "でも身元も不確かなよそ者に重要な装備を任せるのは少し……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But letting a foreigner touch such important equipment is─"
L5_1.m_Talk_ENG = L6_1
L6_1 = "但是怎麼可以把這麼重要的設備，交給一個來路不明的人……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่การให้คนต่างแดนมาแตะต้องอุปกรณ์สำคัญแบบนั้นมัน–"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng để một người ngoài chạm vào thiết bị quan trọng như vậy là–"
L5_1.m_Talk_VTN = L6_1
L6_1 = "可是让一个身份不明的外乡人碰重要装备有点……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber einen Fremden eine so wichtige Ausrüstung berühren zu lassen, ist ─"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais on ne peut pas laisser un étranger poser la main sur un équipement aussi─"
L5_1.m_Talk_FRA = L6_1
