L11_1 = 30
L9_1[L10_1] = L11_1
L10_1 = "우왓?! 방금 대포가 작동한 건가?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "うわっ！？　今の、大砲が作動したのか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "What?! Did that thing just fire?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "哇？！剛才是大砲的聲音嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "หา?! เมื่อกี้มันเพิ่งยิงเหรอ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cái gì?! Nó vừa bắn à?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "哇！哇！刚才大炮是启动了吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Was?! Hat das Ding gerade gefeuert?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Ouah ? Je rêve, ou cette chose vient de tirer ?"
L9_1.m_Talk_FRA = L10_1
