L12_1 = "BORDER_ACT1_STAGE3_START@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4500107
L11_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_PRIDE"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L11_1.m_Pos = "C"
L12_1 = "자동 장치가 제대로 작동하는지 테스트했다. 다행히 부품을 교체할 필요는 없겠어."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "自動装置がちゃんと動いてるかテストしてみたんだ。幸い部品を入れ替える必要はなさそうだな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I was testing to see if the automation device still worked. Thankfully, this one doesn't need any parts replaced."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我剛在測試自動裝置是否可以正常啟動，幸好不需要更換零件。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ผมลองทดสอบดูน่ะว่าอุปกรณ์อัตโนมัติยังทำงานมั้ย โชคดีที่อันนี้ไม่ต้องใช้แถมเปลี่ยนอะไหล่แล้วด้วย"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi đang kiểm tra xem thiết bị tự động hóa có còn hoạt động không. Rất may, cái này không cần phải thay thế linh kiện nào cả."
L11_1.m_Talk_VTN = L12_1
L12_1 = "我测试了一下自动装置能否正常运行。好在不需要更换零部件。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich habe getestet, ob das Automatisierungsgerät noch funktioniert. Zum Glück müssen hier keine Teile ausgetauscht werden."
L11_1.m_Talk_DEU = L12_1
L12_1 = "J'effectuais juste un test pour m'assurer que le dispositif d'automatisation fonctionne toujours. Heureusement, celui-ci n'a pas besoin d'être remplacé."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "BORDER_ACT1_STAGE3_START@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500107
L12_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_HATE"
L12_1.m_Face = L13_1
L13_1 = "WATT_BORDER_NULL_ARMED"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "m_Crash"
L12_1[L13_1] = 20
L13_1 = "테스트고 자시고 대포를 멋대로 쏴 버리면 어쩌자는 거야?!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "テストも何も、勝手に大砲を撃つなんてあり得ねえだろ！？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Test or not, you can't just fire a cannon at your own will!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "我不管你在測試什麼，怎麼可以隨便發射大砲？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "จะทดสอบหรืออะไรก็เถอะ คุณจะยิงปืนใหญ่ตามใจไม่ได้นะ!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Kiểm tra hay không thì anh cũng không thể tùy ý bắn đại bác được!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "就算是测试，也不能随意开炮啊？！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Test oder nicht, du kannst doch nicht einfach eine Kanone abfeuern!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Test ou non, qui t'a autorisé à tirer ainsi à ta guise ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "BORDER_ACT1_STAGE3_START@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500107
L13_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_LAUGH"
L13_1.m_Face = L14_1
L13_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L13_1.m_Pos = "C"
L14_1 = "걱정 마라. 사람이 없는 곳으로 쐈으니까."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "心配するな。人のいないところへ撃ったから。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Don't worry. I aimed it away from where anyone lives."
L13_1.m_Talk_ENG = L14_1
L14_1 = "放心，我是朝沒有人的地方發射。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ไม่ต้องห่วงหรอก ผมเล็งไปทางที่ไม่มีคนอยู่แล้ว"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đừng lo. Tôi nhắm nó ra khỏi nơi có người ở."
L13_1.m_Talk_VTN = L14_1
L14_1 = "别担心，我朝着没人的地方射的。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Keine Sorge. Ich habe dorthin gefeuert, wo niemand lebt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Pas d'inquiétude. Je n'ai pas visé d'habitations."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "BORDER_ACT1_STAGE3_START@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4500107
L14_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L14_1.m_Pos = "C"
L15_1 = "실제로 쏴 보는 것만큼 확실한 검증법도 없지 않나?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "実際に撃ってみるのが一番確実な検証方法だろう？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Isn't doing a test fire the surest way to know if it works?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "實際發射看看才知道有沒有壞吧？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "จะรู้แน่ว่าใช้ได้มั้ยก็มีแต่ต้องลองยิงดูไม่ใช่เหรอ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Không phải thử lửa là cách chắc chắn nhất để biết nó có hoạt động hay không à?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "没有比实际发射更确切的验证方法了吧？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ist die Durchführung eines Feuertests nicht der sicherste Weg, um herauszufinden, ob es funktioniert?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Pour vérifier que quelque chose fonctionne il faut bien le tester, n'est-ce pas ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "BORDER_ACT1_STAGE3_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4500107
L15_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "WATT_BORDER_NULL_ARMED"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "젠장, 쐐기창 한 발이 얼마짜린지나 알아? 아무데나 쏴 버리면 땅속에 박혀서 회수도 못한다고!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "くそ、くさび槍一発がいくらなのか知ってんのか？　むやみに撃つと、地面に深く刺さって回収もできねえんだぞ！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Dammit. Do you even know how much a Ironshot Spear costs?! If that thing goes in too deep into the ground we won't be able to recover it!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "該死，你知道一枚楔子砲要多少錢嗎？你這樣隨便亂發射，跟把錢扔水裡有什麼不一樣！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "บ้าจริง รู้บ้างมั้ยเนี่ยว่าฉมวกกระสุนเหล็กมันราคาเท่าไหร่? ถ้ามันปักพื้นลึกไปเราก็เอากลับมาไม่ได้นะ!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chết tiệt. Anh có biết một Ngọn giáo Ironshot giá bao nhiêu không?! Nếu thứ đó cắm quá sâu vào lòng đất, chúng ta sẽ không thể thu hồi nó!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "可恶，你知道一发楔子枪要多少钱吗？你那样随便射出去，扎进地里的话连回收都回收不了！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Verdammt. Weißt du überhaupt, wie viel ein Keilspeer kostet?! Wenn das Ding zu tief in den Boden eindringt, können wir es nicht bergen!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Bon sang ! Tu sais combien ça coûte, un harpon Salvefer ? Si cette chose s'enfonce trop profondément dans le sol, on ne pourra jamais la récupérer !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "BORDER_ACT1_STAGE3_START@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4500107
L16_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
