L16_1.m_fWaitTime = 0
L17_1 = "UNIT_IDLE"
L16_1.m_Face = L17_1
L16_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L16_1.m_Pos = "C"
L17_1 = "미안하군. 가격을 고려해 무기를 써 본 적이 없어서."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "すまないな。値段を考えて武器を使ったことがなくて。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I'm sorry about that. I've never had to think of costs when using any weapon before."
L16_1.m_Talk_ENG = L17_1
L17_1 = "對不起，我使用武器時從來沒有考慮過錢的問題。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เรื่องนั้นต้องขอโทษด้วย เวลาต้องใช้อาวุธผมไม่เคยคิดเรื่องราคามาก่อนเลย"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi xin lỗi về điều đó. Tôi chưa bao giờ phải nghĩ đến chi phí khi sử dụng bất kỳ loại vũ khí nào trước đây."
L16_1.m_Talk_VTN = L17_1
L17_1 = "抱歉……我以前从来不用考虑武器使用的成本……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das tut mir leid. Ich musste beim Einsatz einer Waffe noch nie an die Kosten denken."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mes excuses. Je n'ai jamais eu à considérer la chose lors de mes utilisations précédentes."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
