L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4500107
L19_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L20_1 = "L"
L19_1.m_Pos = L20_1
L20_1 = "손 봐야 할 장비가 몇 개 더 있어. 그것도 같이 봐 줄 수 있을까?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "手入れが必要な装備が他に何個かある。そっちも見てくれない？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "There's a couple more pieces of equipment that require maintenance. Would you mind looking at those too?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "我還有幾個設備需要修理，你可以幫我看一下嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ยังมีอุปกรณ์ที่ต้องบำรุงรักษาอยู่อีกสองเครื่องนะ ช่วยดูให้ด้วยได้มั้ย?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Có một vài thiết bị cần bảo trì. Anh có phiền nhìn qua chúng không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "还有几台需要修理的装备，那些你能也一起看看吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Es gibt noch ein paar weitere Ausrüstungsgegenstände, die gewartet werden müssen. Würde es dir etwas ausmachen, sie dir auch anzusehen?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Je vois d'autres installations qui mériteraient un petit coup de polish, ici. Tu veux bien y jeter un coup d'œil ?"
L19_1.m_Talk_FRA = L20_1
