L22_1 = "필요하다면 얼마든지."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "必要ならいくらでも。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Not at all. Lead the way."
L21_1.m_Talk_ENG = L22_1
L22_1 = "有需要的話隨時找我。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ไม่มีปัญหา พาไปเลย"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tất nhiên là không rồi. Cô dẫn đường đi."
L21_1.m_Talk_VTN = L22_1
L22_1 = "好，都交给我吧。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Überhaupt nicht."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Bien sûr, je te suis."
