L45_1 = "BORDER_ACT1_STAGE3_START@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4500107
L44_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "PITER_BORDER_NULL_NAMED"
L44_1.m_CharStrID = L45_1
L45_1 = "L_M_I"
L44_1.m_Pos = L45_1
L45_1 = "기계를 잘 알면 혹시 이 오토바이도 한 번 봐 줄 수 있어요?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "機械に詳しいんだったら、ひょっとしてこのバイクも見てもらえますか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "If you know a lot about machines, could you perhaps take a look at this motorbike?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "既然你這麼精通機器，那可以幫我看一下這台車嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ถ้าคุณรู้เรื่องเครื่องจักร งั้นช่วยดูมอเตอร์ไซค์นี่ให้หน่อยได้มั้ยนะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nếu anh biết nhiều về máy móc, anh có thể xem qua chiếc xe máy này không?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "你很了解机器的话，能帮我看看这台摩托车吗？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wenn Sie sich mit Maschinen auskennen, könnten Sie sich vielleicht auch dieses Motorrad ansehen?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Puisque vous êtes à l'aide avec les machines, vous voulez bien regarder un peu cette bécane ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
