L47_1 = "BORDER_ACT1_STAGE3_START@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4500107
L46_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_IDLE"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L47_1 = "R"
L46_1.m_Pos = L47_1
L47_1 = "트라이크로군. 꽤 구형 모델 같은데."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "トライクだな。ずいぶん旧型のモデルのようだが。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It's a trike. And an old model at that."
L46_1.m_Talk_ENG = L47_1
L47_1 = "原來是三輪車，而且好像是舊款。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "มันเป็นสามล้อนี่ รุ่นเก่าด้วย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đó là trike đấy. Lại là một mẫu cổ nữa."
L46_1.m_Talk_VTN = L47_1
L47_1 = "是TRIKE系列的啊。好像是老款车型呢。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Es ist ein Dreirad. Und noch dazu ein altes Modell."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oh, un trike. Et un ancien modèle avec ça."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "BORDER_ACT1_STAGE3_START@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 4500107
L47_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "PITER_BORDER_NULL_NAMED"
L47_1.m_CharStrID = L48_1
L48_1 = "L"
L47_1.m_Pos = L48_1
L48_1 = "헤헤, 아버지가 현역이던 시절에 몰던 거예요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "へへ、お父さんが現役時代に乗ってたものなんです。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hehe! It was what my father used to ride when he was young."
L47_1.m_Talk_ENG = L48_1
L48_1 = "嘿嘿，爸爸年輕時騎的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฮี่ฮี่! มันของพ่อผมตอนปฏิบัติหน้าที่ล่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Hê hê! Đó là của bố tôi khi ông ấy đang làm nhiệm vụ."
L47_1.m_Talk_VTN = L48_1
L48_1 = "嘿嘿，这车是我父亲在役时骑的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hehe, mein Vater ist damit gefahren, als er jung war."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Hé hé ! C'était le bolide de mon père dans sa jeunesse."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "BORDER_ACT1_STAGE3_START@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4500107
L48_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_LAUGH"
L48_1.m_Face = L49_1
L48_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L49_1 = "R"
L48_1.m_Pos = L49_1
L49_1 = "그렇군. 고칠 수 있을지는 모르겠지만, 한 번 시도해 보지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そうか。直せるかはわからないが、一度やってみよう。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I see. I don't know if I'll be able to fix it, but I'll give it a shot."
L48_1.m_Talk_ENG = L49_1
L49_1 = "原來如此，不知道還能不能修，我試試。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เอาสิ ไม่รู้หรอกนะว่าซ่อมได้มั้ย แต่จะลองดูแล้วกัน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi hiểu rồi. Tôi không biết liệu tôi có thể sửa nó không, nhưng tôi sẽ thử."
L48_1.m_Talk_VTN = L49_1
L49_1 = "原来如此。虽然不知道能不能修好，我试试吧？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Verstehe. Ich weiß nicht, ob ich es reparieren kann, aber ich werde es versuchen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je vois. Je ne suis pas sûr d'avoir tout ce qui faut pour le réparer, mais je vais voir ce que je peux faire."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
