L4_1 = "BORDER_ACT1_STAGE3_START@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4500107
L3_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "수고했어. 하루만에 생각보다 많은 일을 해결해 줬네."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "お疲れ様。一日で思ったより多くのことを解決してくれたね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Great job. Didn't think you'd be able to do this much in one day."
L3_1.m_Talk_ENG = L4_1
L4_1 = "辛苦了，沒想到一天之內解決不少事呢。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เยี่ยมมาก ไม่นึกว่าวันเดียวคุณจะทำอะไรได้เยอะขนาดนี้"
L3_1.m_Talk_THA = L4_1
L4_1 = "Anh đã làm rất tốt. Không nghĩ rằng anh có thể làm được nhiều thứ như vậy trong một ngày."
L3_1.m_Talk_VTN = L4_1
L4_1 = "辛苦你了。才一天时间，你就解决了比我想的更多的事呢。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Gute Arbeit. Ich hätte nicht gedacht, dass du so viel an einem Tag schaffen würdest."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Bon travail. Je ne pensais pas que tu pourrais faire autant en une seule journée."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "BORDER_ACT1_STAGE3_START@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4500107
L4_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "이렇게 눈에 띄게 돌아다녀도 괜찮겠나? 주민들을 자극할 수도 있을 텐데?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "こんなに目立ってもいいのか？　住民を刺激することになるかもしれないのに。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You sure it's okay for me to go around town fixing stuff like this? What if I aggravate the villagers?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我這樣到處走沒關係嗎？居民不會覺得礙眼嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แน่ใจเหรอว่าผมซ่อมอะไรไปทั่วเมืองแบบนี้จะไม่เป็นไร? เกิดผมไปทำให้ชาวบ้านโมโหขึ้นมาล่ะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô có chắc là tôi có thể đi quanh thị trấn để sửa những thứ như thế này không? Nếu tôi làm dân làng giận dữ hơn thì sao?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "你确定让我这么张扬地四处露面没有关系吗？会不会刺激到居民们？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Bist du sicher, dass es in Ordnung ist, wenn ich durch die Stadt ziehe und solche Dinge repariere? Was ist, wenn ich die Dorfbewohner verärgere?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ça ne te dérange vraiment pas que je me promène dans la ville comme ça pour réparer des trucs ? Et si on me posait des questions ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "BORDER_ACT1_STAGE3_START@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4500107
L5_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "눈에 띄는 편이 좋아. 주민들에게 당신이 그 큐리안과 다른 사람이란 걸 각인시키려면."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "目立った方がいい。住民にあなたがあのキュリアンとは違う人だと認識させるためにはね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "It's better that they see you. It'll help differentiate you from the Curian they think you are."
L5_1.m_Talk_ENG = L6_1
L6_1 = "這樣比較好，這樣居民才會知道你和那個庫里安是不同人。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ให้พวกเขาเห็นหน้าคุณน่ะดีแล้วนะ มันจะได้ช่วยแยกคุณออกจากคิวเรี่ยนคนที่พวกเขาคิดว่าคุณเป็นน่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tốt hơn là để họ nhìn thấy anh. Nó sẽ giúp phân biệt anh với Curian trong suy nghĩ của họ."
L5_1.m_Talk_VTN = L6_1
L6_1 = "张扬一点好。要想让居民们知道你跟那个奎里安是不同的人。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Es ist besser, dass sie dich sehen. Es wird ihnen helfen, dich von dem Curian zu unterscheiden, für den sie dich halten."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je préfère que les villageois s'habituent à toi. Ça les aidera à te différencier du Curian qu'ils connaissent."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "BORDER_ACT1_STAGE3_START@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4500107
L6_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L7_1 = "R"
L6_1.m_Pos = L7_1
L7_1 = "……난 총사대장 제라드 큐리안이다. 언제까지 동명이인으로 남을 생각은 없어."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "……私は銃士隊長のジェラード・キュリアンだ。いつまでも同名異人でいるつもりはない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "...But I am Curian. General Musketeer of the Musketeer Division. I have no intention staying as \"the other Curian\"."
L6_1.m_Talk_ENG = L7_1
L7_1 = "……我是隊長 傑瑞德· 庫里安，不是一個只是同名同姓的人。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "... แต่ผมคือคิวเรี่ยน ผู้บัญชาการของหน่วยแม่นปืน ผมไม่ได้ตั้งใจจะอยู่ที่นี่ในฐานะ \"คิวเรี่ยนอีกคน\" หรอกนะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "...Nhưng tôi là Curian. Tổng tư lệnh của Sư đoàn Thiện xạ. Tôi không có ý định ở lại với tư cách \"Curian khác\"."
L6_1.m_Talk_VTN = L7_1
L7_1 = "……我是皇家第1火枪手队的队长杰拉德·奎里安。我没打算一直以其他的身份留下来。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "... Aber ich bin Gerard Curian. Hauptmann der Musketier-Division. Ich habe nicht die Absicht, für immer für eine andere Person gehalten zu werden."
L6_1.m_Talk_DEU = L7_1
L7_1 = "... Mais je suis Curian. Gerard Curian, Général des Mousquetaires. Je n'ai pas l'intention de rester un simple homonyme."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "BORDER_ACT1_STAGE3_START@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500107
L7_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L8_1 = "L"
L7_1.m_Pos = L8_1
L8_1 = "촌장님이 했던 말 기억해 둬."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "村長の言葉をよく覚えておいて。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Keep in mind what Chief O'Neil said to you."
L7_1.m_Talk_ENG = L8_1
L8_1 = "記住村長說過的話。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "อย่าลืมที่หัวหน้าโอนีลบอกสิ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Hãy ghi nhớ những gì Trưởng làng O'Neil đã nói với anh."
L7_1.m_Talk_VTN = L8_1
L8_1 = "记住村长说的话。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Denk daran, was Dorfvorsteher O'Neil zu dir gesagt hat."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Certes, mais n'oublie pas ce que le chef O'Neil disait tout à l'heure."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "BORDER_ACT1_STAGE3_START@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4500107
L8_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "저 사람들에게 당신이 과거에 어떤 큐리안이었는지는 중요치 않아."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "住民たちにあなたが過去どんなキュリアンだったのかは重要じゃない。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "To them, it doesn't matter if you're the Curian from the past or not."
L8_1.m_Talk_ENG = L9_1
L9_1 = "對於他們來說，你過去是什麼樣的庫里安並不重要。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "สำหรับพวกเขา คุณจะเป็นคิวเรี่ยนจากในอดีตมั้ยน่ะไม่สำคัญหรอกนะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Đối với họ, không quan trọng anh có phải là Curian trong quá khứ hay không."
L8_1.m_Talk_VTN = L9_1
L9_1 = "对于居民们来说，作为奎里安的你，过去是怎样的并不重要。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Für sie spielt es keine Rolle, ob du der Curian aus der Vergangenheit bist oder nicht."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Pour ces gens, peu importe que tu sois le Curian du passé ou non."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "BORDER_ACT1_STAGE3_START@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500107
L9_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "지금 이곳에 머무는 큐리안이 얼마나 필요한 존재인지가 중요한 거지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "今ここにいるキュリアンがどんなに必要な存在なのかが重要なんだ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "What matters is how much they need \"this\" Curian in their village right now."
L9_1.m_Talk_ENG = L10_1
L10_1 = "重要的是，他們有多需要現在留在這裡的庫里安。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เรื่องสำคัญคือตอนนี้พวกเขาจำเป็นต้องมีคิวเรี่ยน \"คนนี้\" ในหมู่บ้านขนาดไหน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Điều quan trọng là họ cần Curian \"này\" trong làng của họ ngay bây giờ."
L9_1.m_Talk_VTN = L10_1
L10_1 = "重要的是现在的奎里安对他们来说是非常必要的存在。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Was zählt, ist, wie sehr sie „diesen“ Curian gerade jetzt in ihrem Dorf brauchen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Ce qui compte, c'est qu'ils ont besoin du Curian d'aujourd'hui. Ils ont besoin de lui, maintenant."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "BORDER_ACT1_STAGE3_START@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4500107
L10_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "UNIT_IDLE"
L10_1.m_Face = L11_1
L10_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L11_1 = "R"
L10_1.m_Pos = L11_1
L11_1 = "알겠다. 명심해 두지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "わかった。肝に銘じておこう。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "All right. I'll remember it."
L10_1.m_Talk_ENG = L11_1
L11_1 = "好，我會銘記在心的。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เข้าใจละ ผมจะจำไว้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Được rồi. Tôi sẽ nhớ nó."
L10_1.m_Talk_VTN = L11_1
L11_1 = "知道了，我会记住的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "In Ordnung. Ich werde es im Hinterkopf behalten."
L10_1.m_Talk_DEU = L11_1
L11_1 = "D'accord. Je m'en souviendrai."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "BORDER_ACT1_STAGE3_START@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4500107
L11_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_LAUGH"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "그리고 고마워. 당신이 손 봐 준 덕분에 마을의 상황도 많이 나아졌어."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それから、ありがとう。手入れをしてくれたおかげで、村の状況もだいぶ良くなった。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Also, thanks. The village is doing a lot better because of you."
L11_1.m_Talk_ENG = L12_1
L12_1 = "另外，謝謝你，多虧你的幫忙，村裡的情況好很多。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แล้วก็ขอบคุณนะ หมู่บ้านดีขึ้นเยอะเพราะคุณเลย"
L11_1.m_Talk_THA = L12_1
L12_1 = "Dù sao cũng cảm ơn. Ngôi làng đang tốt hơn rất nhiều nhờ có anh đấy."
L11_1.m_Talk_VTN = L12_1
L12_1 = "还有，谢谢你。多亏了你帮忙，村里的情况好转了不少。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Und danke. Dank dir geht es dem Dorf viel besser."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Au fait, merci. Grâce à toi, notre village ne s'est jamais porté aussi bien."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "BORDER_ACT1_STAGE3_START@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500107
L12_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L13_1 = "L"
L12_1.m_Pos = L13_1
L13_1 = "몸상태는 좀 어때?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "体の方はどう？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "How's your condition, though?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "身體狀態如何？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ว่าแต่ อาการคุณเป็นยังไงบ้างล่ะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tình trạng của anh thế nào rồi?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "身体恢复得怎么样了？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wie fühlst du dich?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Plus important, comment te sens-tu ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "BORDER_ACT1_STAGE3_START@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500107
L13_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_PRIDE"
L13_1.m_Face = L14_1
L13_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "괜찮다. 깨어났을 때보다는 많이 회복됐어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "大丈夫だ。目覚めた時よりはだいぶ回復している。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Good. Better than when I woke up."
L13_1.m_Talk_ENG = L14_1
L14_1 = "還好，已經比剛醒來時好很多。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ดีอยู่นะ ดีกว่าตอนเพิ่งฟื้น"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tốt. Tốt hơn so với khi tôi thức dậy."
L13_1.m_Talk_VTN = L14_1
L14_1 = "没事了。比刚醒时好多了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Gut. Mir geht es viel besser als heute Morgen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Bien. Mieux qu'à mon réveil, en tout cas."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "BORDER_ACT1_STAGE3_START@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4500107
L14_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L15_1 = "R"
L14_1.m_Pos = L15_1
L15_1 = "이 정도면 그만 여길 떠나도 괜찮…"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "このくらいならもうここを離れても大丈……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I think I'm good enough to leave─"
L14_1.m_Talk_ENG = L15_1
L15_1 = "以現在的狀態，應該可以離開…"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมว่าผมจ่ายหนี้แล้ว และก็น่าจะไปแล้ว–"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi nghĩ mình đã trả xong nợ và có thể rời khỏi–"
L14_1.m_Talk_VTN = L15_1
L15_1 = "这种程度的话离开这里也没问……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich denke, es geht mir gut genug, um ─"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Je pense que je vais pouvoir vous laiss─"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
