L18_1 = "BORDER_ACT1_STAGE3_START@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4500107
L17_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L18_1 = "커헉…!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ぐはっ……！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Kuh...!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "咳咳…！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "อึ้ก...!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Khụ...!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "咳嚇……！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Au!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ouch... !"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "BORDER_ACT1_STAGE3_START@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4500107
L18_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "UNIT_IDLE"
L18_1.m_Face = L19_1
L18_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "별로 괜찮지 않아 보이네. 제대로 서있지도 못하잖아."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "あまり大丈夫に見えないけど。まともに立ててないじゃない。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I don't think you're doing so good. You can barely stand on your own two feet."
L18_1.m_Talk_ENG = L19_1
L19_1 = "看起來不像還好，根本連站都不穩。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ดูทรงยังไม่น่าจะดีนักนะ แค่ยืนเองยังแทบไม่ไหวเลย"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tôi không nghĩ rằng anh ổn đâu. Anh hầu như không thể đứng vững trên đôi chân của mình."
L18_1.m_Talk_VTN = L19_1
L19_1 = "看起来不是很好。你连站都站不稳。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ich glaube nicht, dass es dir so gut geht. Du kannst kaum auf deinen eigenen Beinen stehen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "On dirait que tu n'es pas encore complètement remis, après tout. Tu tiens à peine debout sur tes jambes !"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
