L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4500107
L20_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L21_1 = "그렇게 갑자기 다리를 걸면 보통은 쓰러지지 않나?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そんな風に突然足をかけられたら普通は倒れるんじゃないか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Anyone will fall if you trip them like that."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你那樣突然絆倒我，會跌倒不是很正常的嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คุณขัดขาแบบนั้นใครก็ล้มทั้งนั้นแหละ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Bất cứ ai cũng sẽ ngã nếu cô ngáng chân người ta như thế."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你那样突然使绊子的话，一般人都会倒吧？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Jeder würde hinfallen, wenn man ihm so ein Bein stellen würde."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Après un châssé pareil, n'importe qui perdrait l'équilibre !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "BORDER_ACT1_STAGE3_START@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4500107
L21_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "총사대 최강의 카운터가 고작 다리 걸기에 당했다면, 그건 상태가 별로 좋지 않다는 뜻이지."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "銃士隊最強のカウンターが足かけ程度で倒れるなら、あまり具合が良くないってことだね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "But if the strongest Counter in the Musketeer Division gets tripped like that, it means he hasn't fully recovered."
L21_1.m_Talk_ENG = L22_1
L22_1 = "身為射擊隊最強的制裁者，這樣就被絆倒，就表示狀態不太好吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่ถ้าเคาน์เตอร์ที่แข็งแกร่งที่สุดในหน่วยแม่นปืนยังสะดุดล้มแบบนั้นได้ ก็แปลว่าเขายังไม่ฟื้นตัวเต็มที่นี่"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nhưng nếu Counter mạnh nhất trong Sư đoàn Thiện xạ bị vấp ngã như vậy, điều đó có nghĩa là anh ta vẫn chưa hồi phục hoàn toàn."
L21_1.m_Talk_VTN = L22_1
L22_1 = "皇家火枪手最强制裁者会被绊子绊倒，就是意味着身体还没恢复吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Aber wenn der stärkste Counter in der Musketier-Division so einfach hinfällt, bedeutet das, dass er sich noch nicht vollständig erholt hat."
L21_1.m_Talk_DEU = L22_1
L22_1 = "N'importe qui, mais pas le meilleur Counter des Mousquetaires. À moins d'être fortement diminué. "
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
