L26_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "오늘은 이만 병실로 돌아가. 진단은 내일 다시 해 줄 테니까."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "今日はもう病室に戻って。明日また診断してあげるから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You should probably return to your room for the day. I'll be there for your check-up tomorrow."
L26_1.m_Talk_ENG = L27_1
L27_1 = "今天就先回病房吧，明天再替你看診。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "วันนี้คุณกลับไปที่ห้องก่อนเถอะ เดี๋ยวพรุ่งนี้ฉันไปดูอาการให้"
L26_1.m_Talk_THA = L27_1
L27_1 = "Anh có lẽ nên trở về phòng của mình. Tôi sẽ ở đó để kiểm tra cho anh vào ngày mai."
L26_1.m_Talk_VTN = L27_1
L27_1 = "今天就先回病房吧。明天我再给你做一次诊断。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Du solltest wahrscheinlich für heute in dein Zimmer zurückkehren. Ich werde morgen bei deiner Kontrolluntersuchung da sein."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Tu ferais mieux de retourner dans ta chambre pour aujourd'hui. la journée. Je reviendrai faire un bilan demain."
L26_1.m_Talk_FRA = L27_1
