L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "NOMAD_BORDER_NULL_ADULT"
L34_1.m_CharStrID = L35_1
L35_1 = "낮에 외성 밖으로 고철을 주우러 갔던 아이들이 여태 돌아오지 않았어요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "昼に外郭の外までくず鉄を拾いに行った子供たちが戻ってこないんです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The children who went out to gather metal scraps still haven't returned."
L34_1.m_Talk_ENG = L35_1
L35_1 = "孩子們白天去外城撿廢鐵，到現在都還沒回來。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เด็กๆ ที่ออกไปเก็บเศษเหล็กยังไม่กลับมากันเลยครับ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Những đứa trẻ đi nhặt sắt vụn vẫn chưa về."
L34_1.m_Talk_VTN = L35_1
L35_1 = "白天去外城外面捡废铁的孩子们到现在还没回来！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Die Kinder, die tagsüber die Außenburg verlassen haben, um Altmetall zu sammeln, sind noch nicht zurückgekehrt."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Les enfants sortis récupérer des morceaux de tôle à l'extérieur ne sont toujours pas revenus."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "BORDER_ACT1_STAGE3_START@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4500107
L35_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "NOMAD_BORDER_NULL_ADULT"
L35_1.m_CharStrID = L36_1
L36_1 = "부모님들이 찾으러 나갔는데… 계속 소식이 없어서… 흑…"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "親が探しに行きましたけど……ずっとなんの連絡もなくて……ううっ……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Their parents went out to find them, but... We haven't heard back from any of them... *Sniffle*"
L35_1.m_Talk_ENG = L36_1
L36_1 = "家長都出去找了…可是一直沒有消息…嗚…"
L35_1.m_Talk_TWN = L36_1
L36_1 = "พ่อแม่พวกเขาออกไปตามหาแล้ว แต่ว่า... เราไม่ได้ข่าวคราวจากพวกเขาเลยครับ... *ฮึกฮึก*"
L35_1.m_Talk_THA = L36_1
L36_1 = "Bố mẹ của chúng đã đi tìm, nhưng... Chúng tôi chưa nhận được phản hồi từ bất kỳ ai trong số họ... *Khịt mũi*"
L35_1.m_Talk_VTN = L36_1
L36_1 = "他们的爸爸妈妈都去找了……但一直没有消息……会不会……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ihre Eltern machten sich auf die Suche nach ihnen, aber ... es gibt immer noch keine Neuigkeiten ... *schnief*"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Leurs parents sont sortis pour les retrouver, mais... nous n'avons plus de nouvelles d'eux !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "BORDER_ACT1_STAGE3_START@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4500107
L36_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_SERIOUS"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L37_1 = "L"
L36_1.m_Pos = L37_1
L37_1 = "알겠어. 바로 대원들을 소집해서 수색해 볼게."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "わかった。すぐ隊員を集めて捜索してみる。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Okay. I'll gather my men and search the area."
L36_1.m_Talk_ENG = L37_1
L37_1 = "知道了，我馬上召集隊員找人。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เอาล่ะ ฉันจะรวบรวมคนออกไปค้นหานะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Được rồi. Tôi sẽ tập hợp mọi người và tìm kiếm trong khu vực."
L36_1.m_Talk_VTN = L37_1
L37_1 = "知道了。我马上召集队员去搜寻。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Okay. Ich werde sofort meine Männer rufen und die Gegend absuchen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Compris. Je vais rassembler mes hommes et nous allons fouiller la région."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "BORDER_ACT1_STAGE3_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4500107
L37_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L38_1 = "R"
L37_1.m_Pos = L38_1
L38_1 = "나도 돕지."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "私も手伝おう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I'll help."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我也來幫忙。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ผมจะช่วยด้วย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi sẽ giúp."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我也去。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich werde auch helfen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Laisse-moi t'aider."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "BORDER_ACT1_STAGE3_START@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4500107
L38_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L39_1 = "L"
L38_1.m_Pos = L39_1
L39_1 = "환자는 빠져. 외성 밖은 언제 침식체들이 나타날지 알 수 없어."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "患者は下がってて。外郭の外はいつ侵食体が現れるかわからない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I won't allow it. Outside these walls you never know when a C.O. will appear."
L38_1.m_Talk_ENG = L39_1
L39_1 = "病患別插手，外城外不知何時會出現侵蝕體。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฉันไม่อนุญาต พอออกไปนอกกำแพงนี้แล้วจะเจอวัตถุคอร์รัปต์เข้าเมื่อไหร่ก็ไม่รู้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi sẽ không cho phép điều đó. Bên ngoài những bức tường này, anh không bao giờ biết khi nào V.T.A.M sẽ xuất hiện."
L38_1.m_Talk_VTN = L39_1
L39_1 = "患者就不要插手了。外城外面不知道什么时候会出现侵蚀体。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Das werde ich nicht zulassen. Außerhalb dieser Außenburg weiß man nie, wann ein C. O. auftauchen wird."
L38_1.m_Talk_DEU = L39_1
L39_1 = "C'est hors de question. En dehors de ces murs, on n'est jamais à l'abri d'une attaque de la part des Objets Corrompus."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "BORDER_ACT1_STAGE3_START@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4500107
L39_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L40_1 = "R"
L39_1.m_Pos = L40_1
L40_1 = "그 정도는 각오하고 있다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そのくらいは覚悟している。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "That much I already know."
L39_1.m_Talk_ENG = L40_1
L40_1 = "這我已經有做好心理準備。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เรื่องนั้นผมทราบดีอยู่แล้ว"
L39_1.m_Talk_THA = L40_1
L40_1 = "Điều đó tôi đã biết nhiều rồi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "我有心理准备。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Dessen bin ich mir mehr als bewusst."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je le sais déjà."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "BORDER_ACT1_STAGE3_START@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4500107
L40_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "의사의 소견을 무시하지 마. 지금 같은 밤은 특히 더 위험해."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "医者の意見を無視するな。今みたいな夜は特に危ない。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Don't ignore your doctor's advice. It's especially dangerous on a night like this."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不要把醫生的話當耳邊風，尤其像現在晚上特別危險。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ฟังคำแนะนำของแพทย์บ้าง ยิ่งกลางคืนแบบนี้ก็ยิ่งอันตรายนะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đừng bỏ qua lời khuyên của bác sĩ. Nó đặc biệt nguy hiểm vào một đêm như thế này."
L40_1.m_Talk_VTN = L41_1
L41_1 = "不要无视医生的意见。现在这样的夜晚尤其危险。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ignoriere nicht den Rat deiner Ärztin. In einer Nacht wie dieser ist es besonders gefährlich."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Tu ne devrais pas ignorer les conseils de ton médecin. Par une nuit comme celle-ci, c'est encore plus dangereux."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "BORDER_ACT1_STAGE3_START@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4500107
L41_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_SERIOUS"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L42_1 = "R"
L41_1.m_Pos = L42_1
L42_1 = "방아쇠를 당기는 것 정도는 충분히 가능하다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "引き金を引くくらいなら十分できる。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I still have enough strength to pull the trigger."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我完全可以扣扳機。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ผมยังมีแรงพอจะเหนี่ยวไกได้อยู่"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi vẫn còn đủ sức để bóp cò."
L41_1.m_Talk_VTN = L42_1
L42_1 = "扣动扳机还是没问题的。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich habe immer noch genug Kraft, um den Abzug zu betätigen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Peut-être, mais j'ai encore assez de force pour presser la gâchette."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "BORDER_ACT1_STAGE3_START@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4500107
L42_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L43_1 = "R"
L42_1.m_Pos = L43_1
L43_1 = "나에겐 지금 이곳 사람들에게 큐리안이 어떤 존재인지 보여줄 필요가 있으니 말이지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "私には今ここの人たちにキュリアンがどんな存在なのかを見せる必要があるからな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Besides, I need to show the villagers what kind of person Curian is, don't I?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "因爲對我來說，有必要讓這裡的人知道，庫里安是什麼樣的人。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แล้วก็ ผมจำเป็นต้องให้ชาวบ้านได้เห็นด้วยว่าคิวเรี่ยนเป็นคนยังไงนี่ หรือไม่ใช่?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Bên cạnh đó, tôi cần phải cho dân làng thấy Curian là người như thế nào, phải không?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "另外，这里的人们也会期待奎里安到底是怎样的人吧？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Außerdem muss ich den Dorfbewohnern zeigen, was für ein Mensch Curian wirklich ist, nicht wahr?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Et puis il faut bien que je montre aux villageois qui est ce fameux Curian, non ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
