L46_1 = "BORDER_ACT1_STAGE3_START@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4500107
L45_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "UNIT_IDLE"
L45_1.m_Face = L46_1
L45_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "방금 대사는 나르시스트 같아서 별로였어. 그냥 아이들을 구하고 싶다고 해."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "今のセリフはナルシストっぽくていまいちだったね。単に子供たちを助けたいって言ったら？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "You sounded way too narcissistic just now. Just say you want to help find the children."
L45_1.m_Talk_ENG = L46_1
L46_1 = "剛才的台詞有點像自戀狂，你就說想救人就好。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เมื่อกี้ก็ฟังดูช่างเสียดสีกันไปหน่อยนะ แค่บอกว่าอยากช่วยหาพวกเด็กๆ ก็น่าจะพอแล้ว"
L45_1.m_Talk_THA = L46_1
L46_1 = "Vừa rồi anh nghe có vẻ hơi tự đắc. Chỉ cần nói rằng anh muốn giúp tìm những đứa trẻ thôi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "刚才的台词太自恋了。你还不如直说你想救那些孩子们。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Du hast gerade viel zu narzisstisch geklungen. Sag einfach, dass du bei der Suche nach den Kindern helfen möchtest."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tu ne pouvais pas simplement dire que tu voulais venir en aide aux enfants ? C'était trop cringe comme réplique."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "BORDER_ACT1_STAGE3_START@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4500107
L46_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
