L47_1 = "UNIT_SERIOUS"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L46_1.m_Pos = "C"
L47_1 = "아이들을 구하고 싶다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "子供たちを助けたい。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I want to help find the children."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我想救人。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ผมอยากช่วยหาพวกเด็กๆ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi muốn giúp tìm những đứa trẻ."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我想救孩子们。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich möchte helfen, die Kinder zu finden."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je veux sauver les enfants."
L46_1.m_Talk_FRA = L47_1
