L48_1.m_Face = "UNIT_DESPAIR"
L48_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "m_Crash"
L48_1[L49_1] = 20
L49_1 = "하아, 웬만하면 함부로 앞에 나서지 마."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "はあ、できればむやみに前に出ないでちょうだい。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "*Sigh...* Try not to wander off too much, okay?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "哀，到時候你不要輕舉妄動。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "*เฮ้อ...* อย่าไปไกลนักแล้วกัน ตกลงมั้ย?"
L48_1.m_Talk_THA = L49_1
L49_1 = "*Thở dài...* Cố gắng đừng đi lang thang quá nhiều, được chứ?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "好吧……但最好不要随便出头，可以吗？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "*Seufz* Versuche nicht zu leichtsinnig vorzugehen, okay?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "*Soupir* N'en fais pas trop, d'accord ?"
L48_1.m_Talk_FRA = L49_1
