L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L49_1.m_Pos = "C"
L50_1 = "노력해 보기로 하지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "努力してみるとしよう。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I'll try."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我會努力的。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "จะพยายามนะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi sẽ thử."
L49_1.m_Talk_VTN = L50_1
L50_1 = "我尝试一下。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich werde es versuchen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je vais essayer."
