L51_1 = "BORDER_ACT1_STAGE3_START@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 4500107
L50_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "UNIT_IDLE"
L50_1.m_Face = L51_1
L50_1.m_CharStrID = "ELLA_BORDER_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "혹시라도 침식체와 싸우게 되면 최대한 관절부를 노려. 그나마 갑피가 약한 곳이야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "もし侵食体と戦うことになったら、なるべく関節部を狙って。別のところより甲殻が柔らかいとこだから。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "If you get into a fight with a C.O., aim for its joints. That's where their armor is the weakest."
L50_1.m_Talk_ENG = L51_1
L51_1 = "萬一真的遇到侵蝕體，盡量瞄準關節的地方，側邊連接處是弱點。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ถ้าต้องสู้กับวัตถุคอร์รัปต์ขึ้นมา ก็เล็งที่ข้อต่อนะ เกราะพวกมันตรงนั้นอ่อนแอที่สุด"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nếu anh đánh nhau với V.T.A.M, hãy nhắm vào các khớp của nó. Đó là nơi áo giáp của chúng yếu nhất."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如果要对付侵蚀体，尽量瞄准关节部位。那里的甲皮比较薄弱。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wenn du gegen ein C. O. kämpfen musst, ziel auf seine Gelenke. Dort ist seine Rüstung am schwächsten."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Et si tu tombes sur un O.C., vise ses articulations. C'est là que leur blindage est le plus fin."
L50_1.m_Talk_FRA = L51_1
