L2_1 = "물론 쉽진 않겠지만."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "もちろん簡単ではないと思うけど。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "But then again, it's easier said than done."
L1_1.m_Talk_ENG = L2_1
L2_1 = "不過應該還是不容易對付。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่ก็นั่นแหละ พูดง่ายทำยาก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nhưng một lần nữa, nói thì dễ hơn làm."
L1_1.m_Talk_VTN = L2_1
L2_1 = "当然了，虽说并不容易。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber andererseits ist es leichter gesagt als getan."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais là encore, c'est plus facile à dire qu'à faire."
L1_1.m_Talk_FRA = L2_1
