L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "꾸물거리지 말고 빨리 움직여!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ぐずぐずしてないで早く動け！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Stop squirming around and move!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "大家動作快，趕緊出發吧！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หยุดอ้อยอิ่งแล้วไปกันได้แล้ว!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đừng chần chừ và di chuyển đi!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "别磨蹭，快点行动！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hört auf zu trödeln und bewegt euch!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Restez pas là et mettez-vous en route !"
L5_1.m_Talk_FRA = L6_1
