L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500107
L7_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "WATT_BORDER_NULL_ARMED"
L7_1.m_CharStrID = L8_1
L8_1 = "C_R_M_I"
L7_1.m_Pos = L8_1
L8_1 = "성문을 내려라! 최소한의 병력만 남고 모두 출발한다!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "城門を降ろせ！　最小限の兵力だけ残して全部出発する！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Lower the gates! We leave as few troops as we can behind. Everyone else, march!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "放下城門！只留下最低限度的兵力，其餘全部出動！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ลดประตูลง! เราจะทิ้งกำลังพลไว้ให้น้อยที่สุด ทุกคน หน้าเดิน!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Hạ cổng xuống! Chúng ta sẽ để lại ít quân nhất có thể. Những người khác, hành quân!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "放下城门！只留下最基本的兵力，全体出发！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Lasst die Tore herunter! Wir lassen so wenig Truppen wie möglich zurück. Alle anderen, marschiert!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Abaissez les portes ! On ne laisse que le strict nécessaire pour défendre le village !"
L7_1.m_Talk_FRA = L8_1
