L10_1 = "BORDER_ACT1_STAGE3_START@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500107
L9_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_SURPRISE"
L9_1.m_Face = L10_1
L10_1 = "WATT_BORDER_NULL_ARMED"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "음? 당신이 왜 여기 있는 거지?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "うむ？　なんであんたがここにいるんだ？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Hmm? What are you doing here?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "嗯？你爲什麼在這裡？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "หืมม? คุณมาทำอะไรที่นี่น่ะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Hmm? Anh đang làm gì ở đây?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "嗯？你怎么会在这里？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Hmm? Was machst du denn hier?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Hein ? Qu'est-ce que tu fais ici, toi ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "BORDER_ACT1_STAGE3_START@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4500107
L10_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L10_1.m_Pos = "C"
L11_1 = "실종된 아이들을 구하러 간다고 하더군. 도우러 왔다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "失踪した子供たちを助けに行くらしくてな。手を貸そう。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I'm here to help you find the missing children."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我聽說要去救失蹤的孩子，所以就一起來幫忙。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ผมมาช่วยคุณตามหาเด็กๆ ที่หายตัวไป"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi ở đây để giúp anh tìm những đứa trẻ mất tích."
L10_1.m_Talk_VTN = L11_1
L11_1 = "听说你们要去救失踪的孩子们。我是来帮忙的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich bin hier, um zu helfen, die vermissten Kinder zu finden."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je suis ici pour vous aider à trouver les enfants qui ont disparu."
L10_1.m_Talk_FRA = L11_1
