L14_1 = "BORDER_ACT1_STAGE3_START@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500107
L13_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "WATT_BORDER_NULL_ARMED"
L13_1.m_CharStrID = L14_1
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "흥. 우리더러 뒤처져서 짐만 될 게 뻔한 환자까지 챙기라고? 당장 돌아가."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ふん。遅れてお荷物になるに決まってる患者の面倒まで見ろって？　さっさと帰れ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Hmph! Do you really think we're going to take a patient with us? You will only slow us down. Not a chance."
L13_1.m_Talk_ENG = L14_1
L14_1 = "哼，你在只會扯我們的後腿，我們還要分心照顧病患，你現在立刻回去！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฮึ่ม! นี่คิดจริงๆ เหรอว่าเราจะเอาคนป่วยไปด้วย? คุณมีแต่จะถ่วงพวกเราเท่านั้นแหละ ไม่มีทางซะล่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Hừ! Anh có thực sự nghĩ rằng chúng tôi sẽ mang theo một bệnh nhân với chúng tôi? Anh sẽ chỉ làm vướng chân chúng tôi thôi. Còn lâu."
L13_1.m_Talk_VTN = L14_1
L14_1 = "哼！你觉得我们会带一个病患出城吗？马上回去！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Hmpf! Glaubst du wirklich, wir werden einen Patienten mitnehmen? Du wirst uns nur ausbremsen. Geh schnell zurück!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Peuh ! Tu crois vraiment qu'on va s'encombrer d'un malade comme toi ? Aucune chance, tu ne ferais que nous ralentir."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "BORDER_ACT1_STAGE3_START@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4500107
