L15_1 = "L"
L14_1.m_Pos = L15_1
L15_1 = "당신들 대장에게 허락은 받았어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "君たちの隊長から許可はもらった。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I got permission from your captain."
L14_1.m_Talk_ENG = L15_1
L15_1 = "我有得到你們隊長的允許。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "หัวหน้าอนุญาตให้ผมไปแล้วนะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi đã được cho phép từ Đội trưởng của anh."
L14_1.m_Talk_VTN = L15_1
L15_1 = "我已经征得你们队长的同意了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich habe die Erlaubnis von eurer Kommandantin erhalten."
L14_1.m_Talk_DEU = L15_1
L15_1 = "J'ai obtenu la permission de votre capitaine, pourtant."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
