L17_1 = "L"
L16_1.m_Pos = L17_1
L17_1 = "그리고 걱정처럼 뒤처지지는 않을 거야. 친구가 도와 주기로 했거든."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "それに、心配するほど遅れることはないはずだ。友が手伝ってくれると言ったからな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "And don't worry about me slowing you down. I brought a friend to help me."
L16_1.m_Talk_ENG = L17_1
L17_1 = "放心，我不會扯你們後腿的，我的朋友會幫我。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แล้วก็ไม่ต้องห่วงเรื่องผมจะเป็นตัวถ่วงหรอก ผมพาเพื่อมาช่วยด้วย"
L16_1.m_Talk_THA = L17_1
L17_1 = "Và đừng lo lắng về việc tôi làm anh chậm lại. Tôi mang theo một người bạn để giúp tôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "而且，我不会拖后腿的。我的朋友会帮忙。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Und mach dir keine Sorgen, dass ich euch ausbremse. Ich habe einen Freund mitgebracht, der mir helfen wird."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Et ne t'inquiète pas, je ne vous ralentirai pas. Mon ami ici présent va s'en assurer."
L16_1.m_Talk_FRA = L17_1
