L23_1 = "BORDER_ACT1_STAGE3_START@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4500107
L22_1.m_CutScenStrID = "BORDER_ACT1_STAGE3_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "GUARD_BORDER_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "어떻게 된 거지? 방금 전까지 창고에서 꼼짝도 안 하고 있었는데?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "どういうことだ？　さっきまで倉庫で微動だにしなかったのに？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "How's that possible? It wouldn't even budge inside the storage room."
L22_1.m_Talk_ENG = L23_1
L23_1 = "怎麼回事？它剛剛還在倉庫裡一動也不動的？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เป็นไปได้ยังไง? ตอนอยู่ในห้องเก็บของมันไม่กระดุกกระดิกด้วยซ้ำ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Làm thế nào mà có thể? Nó còn không chịu nhúc nhích bên trong nhà kho."
L22_1.m_Talk_VTN = L23_1
L23_1 = "怎么回事？刚才还在仓库里一动不动呢？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wie ist das möglich? Es hat sich bis eben nicht einmal im Lager von der Stelle gerührt."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Comment est-ce possible ? Encore tout à l'heure à l'entrepôt, il ne bougeait pas d'un pouce !"
L22_1.m_Talk_FRA = L23_1
