L25_1 = "WATT_BORDER_NULL_ARMED"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "좋을 대로 해. 대신 우리 발목만 잡지 말라고."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "好きにしろ。その代わり、俺らの足手まといにはなるなよ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Suit yourself. Just don't hold us back."
L24_1.m_Talk_ENG = L25_1
L25_1 = "你開心就好，但不准扯我們後腿。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แล้วแต่ละกัน แค่อย่าถ่วงเราเป็นพอ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tùy anh thôi. Chỉ cần đừng kéo chân chúng tôi là được."
L24_1.m_Talk_VTN = L25_1
L25_1 = "随你便吧……你只要别拖我们后腿就行。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wie du willst. Aber sei uns ja nicht im Weg!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Bah, fais ce que tu veux. Mais ne t'avise pas de nous gêner."
L24_1.m_Talk_FRA = L25_1
